  ["A la izquierda ves cuántos compañeros hay conectados en cada zona y quiénes son. No hace falta que tengan el addon."] = "Links siehst du, wie viele Begleiter in jeder Zone online sind und wer sie sind. Sie brauchen das Addon nicht.",
  ["A la izquierda, un honor por línea: mejor cazador, campeón de la Arena, mayor donante, mejor artesano, mejor reclutador y fiel a las raids. Pulsa uno y ves sus 10 primeros."] = "Links eine Ehrung pro Zeile: bester Jäger, Arena-Champion, größter Spender, bester Handwerker, bester Werber und treu bei Schlachtzügen. Klicke eine an, um ihre Top 10 zu sehen.",
  ["A los Huesos: %s a %s. ¡La próxima!"] = "Bei Knochen: %s zu %s. Beim nächsten Mal!",
