  ["Activos esta semana"] = "Diese Woche aktiv",
  ["Administración"] = "Verwaltung",
  ["Administración enseña cómo va la conexión, con una prueba de mensajes."] = "Die Verwaltung zeigt, wie die Verbindung läuft, mit einem Nachrichtentest.",
  ["Administración: al cambiar de idioma ya no sale «Una acción de interfaz ha fallado por culpa de un accesorio». El juego no deja que un accesorio recargue la interfaz: escribe /reload."] = "Verwaltung: Beim Sprachwechsel erscheint nicht mehr «Aktion der Benutzeroberfläche wegen eines AddOns fehlgeschlagen». Das Spiel lässt ein Addon die Oberfläche nicht neu laden: tippe /reload.",
  ["Ahora no"] = "Jetzt nicht",
  ["Ahora no hay nadie más de la hermandad conectado. Cuando haya alguien, sale aquí; si tiene BlazonGuild, con «Retar»."] = "Gerade ist niemand sonst aus der Gilde online. Sobald jemand da ist, erscheint er hier; mit BlazonGuild, mit «Herausfordern».",
  ["Ahora no puede"] = "Kann gerade nicht",
  ["Ahora organizas en %s"] = "Du organisierst jetzt in %s",
  ["Ahora pulsa dónde va %s: un grupo, «Sin grupo» o «Reserva». Si pulsas a otro jugador, se cambian el sitio."] = "Klicke jetzt, wohin %s kommt: eine Gruppe, «Ohne Gruppe» oder «Reserve». Klickst du auf einen anderen Spieler, tauschen sie die Plätze.",
  ["Ahora tienen %s conectados, %s con BlazonGuild."] = "Sie haben jetzt %s online, %s mit BlazonGuild.",
  ["Ahora: %d %s y %d %s."] = "Jetzt: %d %s und %d %s.",
  ["Ajustes del maestro"] = "Einstellungen des Gildenmeisters",
  ["Al abrir el mapa del mundo la ventana se minimiza sola, y vuelve al cerrarlo."] = "Wenn du die Weltkarte öffnest, minimiert sich das Fenster von selbst und kommt beim Schließen zurück.",
  ["Al hablar con un posadero, un aviso te propone una partida. Todo por puntos: aquí no se mueve oro."] = "Wenn du mit einem Gastwirt sprichst, schlägt dir ein Hinweis eine Partie vor. Alles um Punkte: Hier wird kein Gold bewegt.",
  ["Al sortear, los mejores de la Arena son cabezas de serie; el resto se sortea con /roll, que veréis en el chat."] = "Bei der Auslosung sind die Besten der Arena gesetzt; der Rest wird mit /roll ausgelost, was ihr im Chat seht.",
  ["Al terminar, quien la dirigió escribe cómo fue. Queda en la crónica de la hermandad con quién estuvo."] = "Am Ende schreibt der Leiter, wie es lief. Es bleibt in der Chronik der Gilde, mit allen, die dabei waren.",
  ["Al terminar, quien la dirigió escribe el parte, que queda en la crónica."] = "Am Ende schreibt der Leiter den Bericht, der in der Chronik bleibt.",
  ["Alguien"] = "Jemand",
  ["Alianza"] = "Allianz",
  ["Alianza creada"] = "Allianz gegründet",
  ["Alianza «%s»"] = "Allianz «%s»",
  ["Alianza, pestaña «Cartas y avisos»: cartas del líder a los maestros (con quién las ha leído), «puertas abiertas» para mandar a los nuevos a una hermandad y ocultar a alguien en los chats comunes."] = "Allianz, Reiter «Briefe und Hinweise»: Briefe des Anführers an die Gildenmeister (mit wer sie gelesen hat), «offene Türen», um Neue zu einer Gilde zu schicken, und jemanden in den gemeinsamen Chats ausblenden.",
  ["Alter de %s"] = "Twink von %s",
  ["Anillo"] = "Ring",
  ["Anotado por %s el %s."] = "Notiert von %s am %s.",
  ["Anotar"] = "Notieren",
  ["Anotar botín"] = "Beute notieren",
  ["Antes acepta la privacidad: sin eso el addon no envía nada."] = "Akzeptiere zuerst den Datenschutz: Ohne ihn sendet das Addon nichts.",
  ["Antes de conectar con tu hermandad"] = "Bevor du dich mit deiner Gilde verbindest",
  ["Anuncio de hermandad"] = "Gildenankündigung",
