  ["Anuncios"] = "Ankündigungen",
  ["Anuncios, encuestas y todo lo que pasa en la hermandad."] = "Ankündigungen, Umfragen und alles, was in der Gilde passiert.",
  ["Apagado: tu addon no apunta nada tuyo, pero sigues viendo la lista."] = "Aus: Dein Addon trägt nichts von dir ein, aber du siehst die Liste weiterhin.",
  ["Aparta solo dados que puntúen (unos, cincos, tríos…)."] = "Lege nur Würfel beiseite, die punkten (Einsen, Fünfen, Drillinge…).",
  ["Apartar y plantarse"] = "Beiseitelegen und stehen bleiben",
  ["Apartar y tirar"] = "Beiseitelegen und werfen",
  ["Apoyo"] = "Unterstützung",
  ["Apuntado a %s (%s)%s"] = "Angemeldet für %s (%s)%s",
  ["Apuntado por %s, %s."] = "Eingetragen von %s, %s.",
  ["Apuntado: %s, %s"] = "Angemeldet: %s, %s",
  ["Apuntados (%s de %s): %s."] = "Angemeldet (%s von %s): %s.",
  ["Apuntar a mano"] = "Von Hand eintragen",
  ["Apuntar en el libro"] = "Ins Buch eintragen",
  ["Apuntar en la Tesorería el oro del correo (solo lee lo que hace el juego)"] = "Gold aus der Post in die Gildenkasse eintragen (liest nur, was das Spiel tut)",
  ["Apuntar mis muertes y bajas: no"] = "Meine Tode und Abschüsse eintragen: nein",
  ["Apuntar mis muertes y bajas: sí"] = "Meine Tode und Abschüsse eintragen: ja",
  ["Apuntarme"] = "Anmelden",
  ["Aquí no hay capas: estás en una mazmorra, en un barco o volando."] = "Hier gibt es keine Layer: Du bist in einem Dungeon, auf einem Schiff oder fliegst.",
  ["Aquí no hay zona: estás en una mazmorra, en un barco o volando."] = "Hier gibt es keine Zone: Du bist in einem Dungeon, auf einem Schiff oder fliegst.",
  ["Aquí tendréis una pestaña por cada hermandad hermana."] = "Hier habt ihr einen Reiter für jede Schwestergilde.",
  ["Arena"] = "Arena",
  ["Arena, nueva pestaña «Taberna»: los Huesos, un juego de dados por puntos (contra la casa para practicar, o contra alguien de la hermandad)."] = "Arena, neuer Reiter «Taverne»: Knochen, ein Würfelspiel um Punkte (gegen das Haus zum Üben oder gegen jemanden aus der Gilde).",
  ["Arena, nueva pestaña «Torneos»: torneos con cuadro eliminatorio y sorteo con /roll, y veladas con combates anunciados."] = "Arena, neuer Reiter «Turniere»: K.-o.-Turniere mit Auslosung per /roll und Kampfabende mit angekündigten Kämpfen.",
  ["Arena, «Cara a cara»: dos luchadores frente a frente (puntos, rango, récord, sus combates entre ellos), con su vida en directo si los tienes cerca y quién gana al acabar. Se agranda para retransmitir."] = "Arena, «Kopf an Kopf»: zwei Kämpfer im Vergleich (Punkte, Rang, Bilanz, ihre Kämpfe gegeneinander), mit ihrer Gesundheit live, wenn sie in deiner Nähe sind, und dem Sieger am Ende. Lässt sich zum Streamen vergrößern.",
  ["Arena: %s"] = "Arena: %s",
  ["Arena: en «Retos» salen todos los conectados, y se explica cómo retar. Administración: solo marca en rojo los errores de esta versión."] = "Arena: Unter «Herausforderungen» stehen alle, die online sind, und es wird erklärt, wie man herausfordert. Verwaltung: Nur Fehler dieser Version werden rot markiert.",
  ["Armería"] = "Waffenkammer",
  ["Armería: cada objeto sale con su nombre y su icono (antes salía «Objeto 6189» con una interrogación). En tu propio equipo, la ventana del objeto ya no sale repetida al lado."] = "Rüstkammer: Jeder Gegenstand zeigt seinen Namen und sein Symbol (vorher stand dort «Gegenstand 6189» mit einem Fragezeichen). Bei deiner eigenen Ausrüstung erscheint das Fenster des Gegenstands nicht mehr doppelt.",
  ["Armería: la lista del equipo ya no se sale de su panel la primera vez que se abre."] = "Rüstkammer: Die Ausrüstungsliste ragt beim ersten Öffnen nicht mehr aus ihrem Feld.",
  ["Armería: «Ver su equipo» funciona aunque esté lejos (si tiene BlazonGuild, se lo pedimos). Y en los encargos puedes poner el objeto con Mayús+clic o arrastrándolo."] = "Waffenkammer: «Ausrüstung ansehen» geht auch aus der Ferne (hat er BlazonGuild, fragen wir ihn). Und bei Aufträgen kannst du den Gegenstand mit Umschalt+Klick oder durch Ziehen einfügen.",
  ["Arrastra aquí a quien quede de reserva."] = "Zieh hierher, wer in Reserve bleibt.",
  ["Arrastra cada nombre a su grupo y su fila, o púlsalo y luego pulsa dónde va. Al soltarlo sobre otro, se cambian el sitio."] = "Zieh jeden Namen in seine Gruppe und Zeile, oder klicke ihn an und dann dorthin, wo er hin soll. Lässt du ihn auf jemandem los, tauschen sie die Plätze.",
  ["Arreglado: Artesanía y botín se veía con las pestañas una encima de otra."] = "Behoben: Handwerk und Beute zeigte die Reiter übereinander.",
  ["Arreglado: al volver a programar una raid cancelada, seguía cancelada."] = "Behoben: Ein abgesagter Schlachtzug blieb nach dem Neuansetzen abgesagt.",
  ["Arreglado: la Arena y «Se busca» se quedaban a medias (y la Arena enseñaba «Nueva temporada» a todos)."] = "Behoben: Die Arena und «Gesucht» blieben auf halbem Weg stehen (und die Arena zeigte allen «Neue Saison»).",
  ["Arrástralo a un grupo, o púlsalo y luego pulsa dónde va. Clic derecho: sin grupo."] = "Zieh ihn in eine Gruppe, oder klicke ihn an und dann dorthin, wo er hin soll. Rechtsklick: ohne Gruppe.",
  ["Arrástralo para moverlo por el borde del minimapa. /bg minimapa lo oculta."] = "Zieh ihn, um ihn am Rand der Minikarte zu verschieben. /bg minimapa blendet ihn aus.",
  ["Artesanos"] = "Handwerker",
  ["Artesanos de la hermandad"] = "Handwerker der Gilde",
  ["Artesanía y botín"] = "Handwerk und Beute",
  ["Asalto"] = "Angriff",
  ["Asunto"] = "Betreff",
  ["Así funciona Artesanía y botín"] = "So funktioniert Handwerk und Beute",
  ["Así funciona el Mapa"] = "So funktioniert die Karte",
  ["Así funciona el Reclutamiento"] = "So funktioniert die Rekrutierung",
  ["Así funciona la Alianza"] = "So funktioniert die Allianz",
  ["Así funciona la Arena"] = "So funktioniert die Arena",
  ["Así funciona la Sala de guerra"] = "So funktioniert der Kriegsraum",
  ["Así funciona la Tesorería"] = "So funktioniert die Schatzkammer",
  ["Así funciona «Se busca»"] = "So funktioniert «Gesucht»",
  ["Así funcionan las Raids"] = "So funktionieren Schlachtzüge",
  ["Así funcionan los honores"] = "So funktionieren Ehrungen",
  ["Así tu hermandad te ve en la Armería aunque estéis lejos: lo que llevas puesto y su nivel, lo mismo que ve quien te inspecciona en el juego."] = "So sieht dich deine Gilde in der Waffenkammer, auch wenn ihr weit weg seid: was du trägst und seine Stufe, dasselbe, was jeder sieht, der dich im Spiel betrachtet.",
  ["Ausente"] = "Abwesend",
  ["Automático (el del juego)"] = "Automatisch (die des Spiels)",
  ["Autoprueba"] = "Selbsttest",
  ["Autoprueba (Administración o /bg autoprueba): comprueba el addon en tu juego y te da un informe para copiar."] = "Selbsttest (Verwaltung oder /bg autoprueba): prüft das Addon in deinem Spiel und gibt dir einen Bericht zum Kopieren.",
  ["Avisamos a %s. En cuanto contesten, estaréis dentro."] = "Wir haben %s Bescheid gesagt. Sobald sie antworten, seid ihr dabei.",
  ["Avisamos a todos los llamados de que no se hace."] = "Wir sagen allen Gerufenen, dass es ausfällt.",
  ["Aviso final"] = "Letzte Warnung",
  ["Avisos %s"] = "Verwarnungen %s",
  ["Avisos acumulados: %s de 3. Al tercero se abre un caso que decide el maestro."] = "Bisherige Verwarnungen: %s von 3. Bei der dritten wird ein Fall eröffnet, über den der Gildenmeister entscheidet.",
  ["Avistamiento: %s"] = "Sichtung: %s",
  ["Avistamientos"] = "Sichtungen",
  ["Ayuda"] = "Hilfe",
  ["Azshara"] = "Azshara",
  ["Añade antes algún combate."] = "Füge zuerst einen Kampf hinzu.",
  ["Añadir"] = "Hinzufügen",
  ["Añadir combate"] = "Kampf hinzufügen",
  ["Añadir un combate a la velada"] = "Einen Kampf zum Kampfabend hinzufügen",
  ["Aún nadie"] = "Noch niemand",
  ["Aún nadie ha cazado a un buscado."] = "Noch niemand hat einen Gesuchten erlegt.",
  ["Aún nadie ha jugado una partida entre miembros. Las de práctica contra la casa no cuentan."] = "Noch niemand hat eine Partie zwischen Mitgliedern gespielt. Übungspartien gegen das Haus zählen nicht.",
  ["Aún nadie ha votado. "] = "Noch niemand hat abgestimmt. ",
  ["Aún nadie, aparte del jefe."] = "Noch niemand außer dem Anführer.",
  ["Aún nadie."] = "Noch niemand.",
  ["Aún nadie. Cuando alguien entra, dice quién le trajo."] = "Noch niemand. Wer beitritt, sagt, wer ihn mitgebracht hat.",
  ["Aún ninguna. Aquí salen las raids de BlazonGuild que ya empezaron, con cuántos fueron."] = "Noch keiner. Hier erscheinen BlazonGuild-Schlachtzüge, die schon begonnen haben, und wie viele dabei waren.",
  ["Aún ninguno. Cuando la hermandad mate a un jefe de esta banda (con la mayoría del grupo de la hermandad), el addon de quien estaba allí lo apunta solo."] = "Noch keiner. Wenn die Gilde einen Boss dieses Schlachtzugs tötet (mit einer Gruppe, die größtenteils aus der Gilde ist), trägt ihn das Addon von jemandem, der dabei war, von selbst ein.",
  ["Aún no compartes tu equipo. Pulsa «Compartir mi equipo» y tu hermandad verá lo que llevas puesto (se actualiza solo cuando cambias algo)."] = "Du teilst deine Ausrüstung noch nicht. Klicke auf «Meine Ausrüstung teilen», dann sieht deine Gilde, was du trägst (es aktualisiert sich von selbst, wenn du etwas wechselst).",
  ["Aún no conocéis ninguna hermandad. Cuando alguien de la vuestra juegue en grupo con alguien de otra hermandad que use BlazonGuild y publique sus cifras, aparecerá aquí."] = "Ihr kennt noch keine Gilde. Wenn jemand von euch in einer Gruppe mit jemandem einer anderen Gilde spielt, die BlazonGuild nutzt und ihre Zahlen veröffentlicht, erscheint sie hier.",
  ["Aún no conocéis otras hermandades. Aparecen al jugar en grupo (mazmorras, bandas, campos de batalla) con alguien de ellas que use BlazonGuild."] = "Ihr kennt noch keine anderen Gilden. Sie erscheinen, wenn ihr in einer Gruppe (Dungeons, Schlachtzüge, Schlachtfelder) mit jemandem von ihnen spielt, der BlazonGuild nutzt.",
  ["Aún no ha pasado nada. Aquí sale cada muerte y cada baja que apuntan los miembros con el addon."] = "Noch ist nichts passiert. Hier erscheint jeder Tod und jeder Abschuss, den die Mitglieder mit dem Addon eintragen.",
  ["Aún no ha peleado esta temporada."] = "Hat diese Saison noch nicht gekämpft.",
  ["Aún no ha respondido nadie."] = "Noch hat niemand geantwortet.",
  ["Aún no has preguntado nada."] = "Du hast noch nichts gefragt.",
  ["Aún no hay campeón: el primero que gane un duelo se lleva el cinturón."] = "Noch kein Champion: Wer als Erster ein Duell gewinnt, bekommt den Gürtel.",
  ["Aún no hay cartas. El líder de la alianza escribe aquí a los maestros (y, si quiere, a los capitanes)."] = "Noch keine Briefe. Der Anführer der Allianz schreibt hier den Gildenmeistern (und, wenn er will, den Hauptleuten).",
  ["Aún no hay combates esta temporada."] = "Diese Saison gibt es noch keine Kämpfe.",
  ["Aún no hay combates esta temporada. Reta a alguien en «Retos», o batíos en duelo desde el juego: el addon de quien pierde lo apunta solo."] = "Diese Saison gibt es noch keine Kämpfe. Fordere jemanden unter «Herausforderungen» heraus oder duelliert euch im Spiel: Das Addon des Verlierers trägt es von selbst ein.",
  ["Aún no hay combates.%s"] = "Noch keine Kämpfe.%s",
  ["Aún no hay escuadras. "] = "Noch keine Trupps. ",
  ["Aún no hay escuadras. Crea una con un jefe y unos pocos miembros: tendrá su propio chat y podréis llamarla a operaciones."] = "Noch keine Trupps. Erstelle einen mit einem Anführer und ein paar Mitgliedern: Er hat seinen eigenen Chat und ihr könnt ihn zu Operationen rufen.",
  ["Aún no hay escuadras. Las crean los organizadores; cada una tiene su jefe y su propio chat."] = "Noch keine Trupps. Die Organisatoren erstellen sie; jeder hat seinen Anführer und seinen eigenen Chat.",
  ["Aún no hay ficha. La escriben los oficiales: a qué os dedicáis, idioma, días de banda y a quién buscáis."] = "Noch kein Steckbrief. Die Offiziere schreiben ihn: was ihr macht, Sprache, Schlachtzugstage und wen ihr sucht.",
  ["Aún no hay foto del banco. Aparecerá cuando un oficial o un tesorero lo abra con BlazonGuild."] = "Noch kein Foto der Bank. Es erscheint, wenn ein Offizier oder Schatzmeister sie mit BlazonGuild öffnet.",
  ["Aún no hay nadie en este ranking."] = "Noch niemand in dieser Rangliste.",
  ["Aún no hay nadie. Para salir aquí, cada uno abre la ventana de su profesión en el juego y dice «Publicar». Escribe arriba un objeto para buscar quién lo fabrica."] = "Noch niemand. Um hier zu erscheinen, öffnet jeder im Spiel das Fenster seines Berufs und sagt «Veröffentlichen». Gib oben einen Gegenstand ein, um zu finden, wer ihn herstellt.",
  ["Aún no hay ningún cargo."] = "Noch keine Ämter.",
  ["Aún no hay partes. Quien dirige una operación lo escribe al terminarla."] = "Noch keine Berichte. Wer eine Operation leitet, schreibt ihn am Ende.",
  ["Aún no hay tesoreros: los nombra el maestro en «Cuotas». "] = "Noch keine Schatzmeister: Der Gildenmeister ernennt sie unter «Beiträge». ",
  ["Aún no hay torneos. Cualquiera puede crear uno con «Nuevo»: un torneo con cuadro eliminatorio, o una velada con combates anunciados."] = "Noch keine Turniere. Jeder kann eines mit «Neu» erstellen: ein Turnier mit K.-o.-Baum oder einen Kampfabend mit angekündigten Kämpfen.",
  ["Aún no hemos visto ninguna. En el juego, abre la ventana de tu profesión (por ejemplo, Herrería o Alquimia): BlazonGuild te preguntará si quieres publicarla. Solo la ve tu hermandad."] = "Wir haben noch keinen gesehen. Öffne im Spiel das Fenster deines Berufs (zum Beispiel Schmiedekunst oder Alchemie): BlazonGuild fragt, ob du ihn veröffentlichen willst. Nur deine Gilde sieht ihn.",
  ["Aún no se sabe qué lleva."] = "Noch unbekannt, was er trägt.",
  ["Aún no tienes boletos hoy."] = "Du hast heute noch keine Lose.",
  ["Aún no tienes honores. Cazar buscados, donar, fabricar encargos, traer gente o ir a las raids te sube en los rankings."] = "Du hast noch keine Ehrungen. Gesuchte jagen, spenden, Aufträge herstellen, Leute mitbringen oder zu Schlachtzügen gehen bringt dich in den Ranglisten nach oben.",
  ["Aún sin combates esta temporada."] = "Diese Saison noch keine Kämpfe.",
  ["Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Noch kein Kontakt: Er kommt, wenn sich jemand von ihnen mit BlazonGuild einloggt.",
  ["BGE2%s%s"] = "BGE2%s%s",
  ["BT:%s"] = "BT:%s",
  ["Bajar bandera"] = "Flagge einholen",
  ["Bajas de buscados de la otra facción en 90 días."] = "Tötungen gesuchter Gegner der anderen Fraktion in 90 Tagen.",
  ["Bancal del Creador"] = "Shaper's Terrace",
  ["Banco"] = "Bank",
  ["Banco de la hermandad"] = "Gildenbank",
  ["Banda"] = "Schlachtzug",
  ["Banda (opcional)"] = "Schlachtzug (optional)",
  ["Banda de %s desde el nivel %s. En la hermandad tienen el nivel %s (%s conectados ahora).%s"] = "Schlachtzug für %s ab Stufe %s. In der Gilde haben %s die Stufe (%s jetzt online).%s",
  ["Banda o actividad"] = "Schlachtzug oder Aktivität",
  ["Bandas"] = "Schlachtzüge",
  ["Bandas con todos sus jefes derrotados."] = "Schlachtzüge mit allen Bossen besiegt.",
  ["Bandas enteras"] = "Ganze Schlachtzüge",
  ["Barrow Deeps"] = "Barrow Deeps",
  ["Bastión Faucenegra"] = "Blackmaw Hold",
  ["Bastión Krol'dok"] = "Krol'dok Stronghold",
  ["Batíos en duelo desde el juego (clic derecho en su retrato, «Duelo»). Al terminar, el juego dice quién ganó, y el addon de quien pierde lo apunta solo."] = "Duelliert euch im Spiel (Rechtsklick auf sein Porträt, «Duell»). Am Ende sagt das Spiel, wer gewonnen hat, und das Addon des Verlierers trägt es von selbst ein.",
  ["BlazonGuild %s; juego %s, interfaz %s"] = "BlazonGuild %s; Spiel %s, Schnittstelle %s",
  ["BlazonGuild deja de tocar los menús, las placas y el chat del juego. Su ventana sigue igual."] = "BlazonGuild lässt Menüs, Namensplaketten und Chat des Spiels in Ruhe. Sein Fenster bleibt gleich.",
  ["BlazonGuild está listo"] = "BlazonGuild ist bereit",
  ["BlazonGuild funciona entre los addons de los miembros de tu hermandad. Para eso, tu addon tiene que mandar algunos datos a los de tus compañeros. Si aceptas, esto es lo que se comparte:"] = "BlazonGuild funktioniert zwischen den Addons der Mitglieder deiner Gilde. Dafür muss dein Addon einige Daten an die deiner Begleiter senden. Wenn du zustimmst, wird Folgendes geteilt:",
  ["BlazonGuild habla ahora inglés, alemán, francés, italiano, portugués y ruso, además de español."] = "BlazonGuild spricht jetzt Englisch, Deutsch, Französisch, Italienisch, Portugiesisch und Russisch, außer Spanisch.",
  ["BlazonGuild vuelve a poner sus marcas y sus líneas en la interfaz del juego."] = "BlazonGuild setzt seine Markierungen und Zeilen wieder in die Spieloberfläche.",
  ["BlazonGuild — autoprueba %s"] = "BlazonGuild — Selbsttest %s",
  ["Borrar"] = "Löschen",
  ["Borrar escuadra"] = "Trupp löschen",
  ["Borrar la escuadra"] = "Den Trupp löschen",
  ["Borrarlos"] = "Löschen",
  ["Borrarme"] = "Mich abmelden",
  ["Bosque de Argénteos"] = "Silberwald",
  ["Botín de banda"] = "Schlachtzugsbeute",
  ["Botín de las bandas"] = "Beute der Schlachtzüge",
  ["Botón para minimizar (junto a la X): queda una barra pequeña que puedes mover; púlsala para volver."] = "Minimieren-Knopf (neben dem X): Es bleibt eine kleine Leiste, die du verschieben kannst; klicke darauf, um zurückzukehren.",
  ["Bronce"] = "Bronze",
  ["Brujo"] = "Hexenmeister",
  ["Busca antes la hermandad: hace falta alguien suyo conectado."] = "Suche zuerst die Gilde: Jemand von ihnen muss online sein.",
  ["Busca grupo%s como %s"] = "Sucht Gruppe%s als %s",
  ["Busca quién fabrica algo"] = "Finde, wer etwas herstellt",
  ["Busca quién sabe hacer un objeto, susúrrale o hazle un encargo; los encargos cumplidos hacen el ranking de artesanos."] = "Finde, wer einen Gegenstand herstellen kann, flüstere ihn an oder gib einen Auftrag; erfüllte Aufträge bilden die Handwerker-Rangliste.",
  ["Busca un objeto arriba para ver qué sabe hacer, o pulsa «Pedir» para hacerle un encargo."] = "Suche oben einen Gegenstand, um zu sehen, was er herstellen kann, oder klicke «Bestellen», um ihm einen Auftrag zu geben.",
  ["Busca una hermandad y pulsa «Ver su ficha» en alguien suyo."] = "Suche eine Gilde und klicke bei jemandem von ihnen auf «Steckbrief ansehen».",
  ["Buscamos "] = "Wir suchen ",
  ["Buscamos %s"] = "Wir suchen %s",
  ["Buscan grupo"] = "Suchen Gruppe",
  ["Buscando… (el juego también abre su lista de /who; puedes cerrarla)"] = "Suche… (das Spiel öffnet auch seine /who-Liste; du kannst sie schließen)",
  ["Buscar"] = "Suchen",
  ["Buscar grupo"] = "Gruppe suchen",
  ["Buscar por persona u objeto"] = "Nach Person oder Gegenstand suchen",
  ["Buscar una hermandad"] = "Eine Gilde suchen",
  ["Buscas grupo: %s, como %s. Toda la hermandad lo ve. Se quita sola en %s min."] = "Du suchst Gruppe: %s, als %s. Die ganze Gilde sieht es. Es verschwindet von selbst in %s Min.",
  ["Búscale%s y retadle desde el juego: clic derecho en su retrato, «Duelo»."] = "Finde ihn%s und fordere ihn im Spiel heraus: Rechtsklick auf sein Porträt, «Duell».",
  ["Cabeza"] = "Kopf",
  ["Cada combate lo decide el duelo entre los dos, y toda la hermandad se entera de quién pasa y de quién gana."] = "Jeden Kampf entscheidet das Duell zwischen den beiden, und die ganze Gilde erfährt, wer weiterkommt und wer gewinnt.",
  ["Cada día, hasta %s boletos gratis: un número del 1 al 100 cada uno. Un oficial sortea con /roll 1-100."] = "Jeden Tag bis zu %s kostenlose Lose: jeweils eine Zahl von 1 bis 100. Ein Offizier zieht mit /roll 1-100.",
  ["Cada hermandad sigue con su maestro y sus normas; podéis salir cuando quieras."] = "Jede Gilde behält ihren Gildenmeister und ihre Regeln; ihr könnt austreten, wann ihr wollt.",
  ["Cada hermandad sigue con su maestro. La alianza tiene un líder: el maestro de la hermandad que vote más de la mitad de los maestros (si no, la fundadora)."] = "Jede Gilde behält ihren Gildenmeister. Die Allianz hat einen Anführer: den Gildenmeister der Gilde, die mehr als die Hälfte der Gildenmeister wählt (sonst die Gründerin).",
  ["Cada maestro nombra capitanes (entran en «Oficiales de la alianza») y mensajeros."] = "Jeder Gildenmeister ernennt Hauptleute (sie kommen zu «Offiziere der Allianz») und Boten.",
  ["Cada maestro vota a una hermandad. Lidera la que tenga más de la mitad de los votos; si ninguna, la fundadora."] = "Jeder Gildenmeister stimmt für eine Gilde. Es führt die mit mehr als der Hälfte der Stimmen; sonst die Gründerin.",
  ["Cada miembro que mata le suma 1 de recompensa; 2 si le sacaba 10 niveles o más. Por ejemplo: mata a tres de los vuestros y su recompensa es 3."] = "Jedes Mitglied, das er tötet, erhöht sein Kopfgeld um 1; um 2, wenn er 10 Stufen oder mehr darüber war. Beispiel: Er tötet drei von euch, sein Kopfgeld ist 3.",
  ["Cada muerte de un miembro suma 1 a la recompensa del que le mató (2 si le sacaba 10 niveles o más). Quien le mate se lleva la recompensa más 1 punto, y la recompensa vuelve a cero."] = "Jeder Tod eines Mitglieds erhöht das Kopfgeld des Mörders um 1 (um 2, wenn er 10 Stufen oder mehr darüber war). Wer ihn tötet, bekommt das Kopfgeld plus 1 Punkt, und das Kopfgeld fällt auf null.",
  ["Cada nuevo miembro dice quién le trajo, y sale quién trae más gente a la hermandad."] = "Jedes neue Mitglied sagt, wer es mitgebracht hat, und man sieht, wer die meisten Leute in die Gilde bringt.",
  ["Cada nuevo miembro dice quién le trajo, y si cambias de hermandad puedes traerte tu ficha."] = "Jedes neue Mitglied sagt, wer es mitgebracht hat, und wenn du die Gilde wechselst, kannst du deinen Steckbrief mitnehmen.",
