  ["Compartes tu posición con %s."] = "Du teilst deine Position mit %s.",
  ["Compartir mi BattleTag solo con los organizadores, para que una sanción alcance a todos mis personajes"] = "Meinen BattleTag nur mit den Organisatoren teilen, damit eine Sanktion alle meine Charaktere erreicht",
  ["Compartir mi equipo con mi hermandad (Armería)"] = "Meine Ausrüstung mit meiner Gilde teilen (Waffenkammer)",
