  ["Copia de seguridad del libro"] = "Sicherung des Buchs",
  ["Copiar"] = "Kopieren",
  ["Correcto en %d ms%s"] = "Korrekt in %d ms%s",
  ["Crea convocatorias, apúntate con tu personaje y rol, y organiza los grupos arrastrando. La hermandad lo recibe al instante y también aparece en el calendario del juego."] = "Erstelle Aufrufe, melde dich mit deinem Charakter und deiner Rolle an und ordne die Gruppen per Ziehen. Die Gilde erhält es sofort, und es erscheint auch im Spielkalender.",
  ["Creando y firmando…"] = "Wird erstellt und signiert…",
  ["Crear"] = "Erstellen",
  ["Crear grupo"] = "Gruppe erstellen",
  ["Crear la alianza"] = "Die Allianz gründen",
  ["Crear la primera raid"] = "Den ersten Schlachtzug erstellen",
  ["Crear raid"] = "Schlachtzug erstellen",
  ["Crear sala"] = "Raum erstellen",
  ["Crear y apuntarse"] = "Erstellen und anmelden",
  ["Cráter de Un'Goro"] = "Krater von Un'Goro",
  ["Crónica"] = "Chronik",
  ["Cuadro"] = "Turnierbaum",
  ["Cualquier miembro puede crear raids y dirigirlas."] = "Jedes Mitglied kann Schlachtzüge erstellen und leiten.",
  ["Cualquier miembro puede crear sus raids y grupos. Los organizadores, además, gestionan todas las raids de la hermandad y llaman a los oficiales."] = "Jedes Mitglied kann seine Schlachtzüge und Gruppen erstellen. Die Organisatoren verwalten zudem alle Schlachtzüge der Gilde und rufen die Offiziere.",
  ["Cualquier miembro puede crear sus raids. Quien la crea la dirige: ve quién se apunta y con qué rol, manda a reserva, reparte los grupos e invita con un botón."] = "Jedes Mitglied kann seine Schlachtzüge erstellen. Wer ihn erstellt, leitet ihn: sieht, wer sich mit welcher Rolle anmeldet, setzt Leute in die Reserve, verteilt die Gruppen und lädt mit einem Knopf ein.",
  ["Cualquier miembro. Quien la crea la dirige; el maestro y los organizadores gestionan todas."] = "Jedes Mitglied. Wer ihn erstellt, leitet ihn; der Gildenmeister und die Organisatoren verwalten alle.",
  ["Cualquiera"] = "Jeder",
  ["Cualquiera crea una raid con «Nueva raid». Cada uno se apunta con su rol: «Voy», «Quizá» o «No voy»."] = "Jeder erstellt einen Schlachtzug mit «Neuer Schlachtzug». Jeder meldet sich mit seiner Rolle an: «Dabei», «Vielleicht» oder «Nicht dabei».",
  ["Cualquiera es bienvenido."] = "Jeder ist willkommen.",
  ["Cuando acabe el duelo, aquí sale quién gana."] = "Wenn das Duell endet, steht hier der Sieger.",
  ["Cuando alguien confirma que recibió su encargo, cuenta para el artesano que lo hizo. Aún no hay ninguno."] = "Wenn jemand bestätigt, dass er seinen Auftrag erhalten hat, zählt es für den Handwerker, der ihn gemacht hat. Noch keiner.",
  ["Cuando entres con otros personajes de esta cuenta en la hermandad, aparecerán aquí. Solo se muestran juntos si cada uno de ellos lo comparte también."] = "Wenn du dich mit anderen Charakteren dieses Accounts in der Gilde einloggst, erscheinen sie hier. Sie werden nur zusammen angezeigt, wenn jeder von ihnen es ebenfalls teilt.",
  ["Cuando te unas a una hermandad, aquí verás a sus miembros, raids, rankings y todo lo demás, en vivo."] = "Wenn du einer Gilde beitrittst, siehst du hier ihre Mitglieder, Schlachtzüge, Ranglisten und alles andere, live.",
  ["Cuando un oficial o un tesorero abre el banco de la hermandad con BlazonGuild, el addon toma una foto de lo que hay: el oro y los objetos de cada pestaña que puede ver. Aquí sale la última. El addon no saca ni mete nada."] = "Wenn ein Offizier oder Schatzmeister die Gildenbank mit BlazonGuild öffnet, macht das Addon ein Foto des Inhalts: das Gold und die Gegenstände jedes Fachs, das er sehen kann. Hier erscheint das letzte. Das Addon nimmt nichts heraus und legt nichts hinein.",
  ["Cuando veas a un buscado (en tu objetivo o en su placa de nombre), te avisa y lleva una calavera roja sobre el nombre."] = "Siehst du einen Gesuchten (als Ziel oder an seiner Namensplakette), warnt es dich, und er trägt einen roten Totenkopf über dem Namen.",
  ["Cuartos"] = "Viertelfinale",
  ["Cuello"] = "Hals",
  ["Cuevas de los Lamentos"] = "Höhlen des Wehklagens",
  ["Cuidado, está cerca"] = "Vorsicht, er ist in der Nähe",
  ["Cumbre de Roca Negra"] = "Schwarzfelsspitze",
  ["Cumbre de Roca Negra Inferior"] = "Untere Schwarzfelsspitze",
  ["Cumbre de Roca Negra Superior"] = "Obere Schwarzfelsspitze",
