  ["Cumbre de Roca Negra superior"] = "Obere Schwarzfelsspitze",
  ["Cuota semanal (oro; 0 = sin cuota)"] = "Wochenbeitrag (Gold; 0 = kein Beitrag)",
  ["Cuota semanal opcional: en «Resumen» ves cuánto has dado esta semana y cuánto te falta."] = "Optionaler Wochenbeitrag: Unter «Übersicht» siehst du, wie viel du diese Woche gegeben hast und wie viel fehlt.",
  ["Cuota: %s por semana. Esta semana has dado %s%s"] = "Beitrag: %s pro Woche. Diese Woche hast du %s gegeben%s",
  ["Cuota: %s por semana. Esta semana has dado %s: estás al día. ¡Gracias!"] = "Beitrag: %s pro Woche. Diese Woche hast du %s gegeben: alles beglichen. Danke!",
  ["Cuota: %s por semana. Esta semana has dado %s: te faltan %s. Dáselo a un tesorero por comercio o correo."] = "Beitrag: %s pro Woche. Diese Woche hast du %s gegeben: es fehlen %s. Gib es einem Schatzmeister per Handel oder Post.",
  ["Cuotas"] = "Beiträge",
  ["Cuotas de esta semana"] = "Beiträge dieser Woche",
  ["Cuándo (para que la gente se organice)"] = "Wann (damit sich die Leute organisieren)",
  ["Cuándo jugamos: %s."] = "Wann wir spielen: %s.",
  ["Cuándo jugáis"] = "Wann ihr spielt",
  ["Cuándo sueles jugar"] = "Wann du meistens spielst",
  ["Cuánto (5 = 5 de oro; también 2o 50p)"] = "Wie viel (5 = 5 Gold; auch 2g 50s)",
  ["Cuántos"] = "Wie viele",
  ["Cuántos luchadores como mucho"] = "Höchstzahl der Kämpfer",
  ["Cuántos miembros están listos para cada banda y el historial de raids de la hermandad."] = "Wie viele Mitglieder für jeden Schlachtzug bereit sind, und die Schlachtzugsgeschichte der Gilde.",
  ["Cómo fue"] = "Wie es lief",
  ["Cómo funciona"] = "So funktioniert es",
  ["Cómo se apunta"] = "Wie es eingetragen wird",
  ["Cómo se cuenta"] = "Wie gezählt wird",
  ["Cómo se juega"] = "So wird gespielt",
  ["Cómo se juega a los Huesos"] = "So spielt man Knochen",
  ["Cómo va la conexión con tu hermandad, qué compartes y los ajustes de la hermandad."] = "Wie die Verbindung mit deiner Gilde läuft, was du teilst und die Einstellungen der Gilde.",
  ["D"] = "N",
  ["Dale oro a un tesorero por comercio o por correo. Su addon lo apunta solo en el libro, y a ti te llega un «gracias»."] = "Gib einem Schatzmeister Gold per Handel oder Post. Sein Addon trägt es von selbst ins Buch ein, und du bekommst ein «Danke».",
  ["Dar oro"] = "Gold geben",
  ["Datos de tu última sesión, actualizando…"] = "Daten deiner letzten Sitzung, werden aktualisiert…",
  ["Daño"] = "Schaden",
  ["De %s, de «%s», %s."] = "Von %s, aus «%s», %s.",
  ["De %s, hermandad hermana"] = "Von %s, Schwestergilde",
  ["De dónde sale"] = "Woher es kommt",
  ["De quién o para quién"] = "Von wem oder für wen",
  ["Decidido a mano"] = "Von Hand entschieden",
  ["Decir a mi hermandad dónde he visto a jugadores de la otra facción, solo cuando un compañero lo pregunte"] = "Meiner Gilde sagen, wo ich Spieler der anderen Fraktion gesehen habe, nur wenn ein Gildenmitglied fragt",
  ["Decisión tomada"] = "Entscheidung getroffen",
  ["Defensa"] = "Verteidigung",
  ["Deja una barra pequeña para ver el juego. Pulsa la barra para volver."] = "Lässt eine kleine Leiste, damit du das Spiel siehst. Klicke auf die Leiste, um zurückzukehren.",
  ["Dejar de compartir"] = "Nicht mehr teilen",
  ["Dejar de publicar"] = "Nicht mehr veröffentlichen",
  ["Dejar de seguir"] = "Nicht mehr folgen",
  ["Dejarlo así"] = "So lassen",
  ["Denuncia enviada"] = "Meldung gesendet",
  ["Denuncia nueva"] = "Neue Meldung",
  ["Denunciar"] = "Melden",
  ["Denuncias y silencios"] = "Meldungen und Stummschaltungen",
  ["Derrota"] = "Niederlage",
  ["Desaparece de la lista para todos."] = "Es verschwindet für alle aus der Liste.",
  ["Desolace"] = "Desolace",
  ["Deutsch"] = "Deutsch",
  ["Devolver"] = "Zurückgeben",
  ["Directorio de mazmorras con quién de la hermandad tiene el nivel, y buscador de grupo: forma uno o únete por rol desde aquí."] = "Verzeichnis der Dungeons mit wer aus der Gilde die Stufe hat, und Gruppensuche: Bilde eine oder tritt hier nach Rolle bei.",
  ["Dirige: %s."] = "Leitung: %s.",
  ["Donantes"] = "Spender",
  ["Druida"] = "Druide",
  ["Duelos apuntados en la temporada de la Arena."] = "In der Arenasaison eingetragene Duelle.",
  ["Duelos de la Arena"] = "Arenaduelle",
  ["Duelos entre miembros de la hermandad, con su clasificación. El resultado lo lee el propio juego al terminar el duelo. Sin apuestas."] = "Duelle zwischen Gildenmitgliedern, mit ihrer Rangliste. Das Spiel selbst liest das Ergebnis am Ende des Duells. Keine Wetten.",
  ["Dun Morogh"] = "Dun Morogh",
  ["Dáselo a un tesorero por comercio o por correo: se apunta solo en la Tesorería. Los tesoreros los nombra el maestro."] = "Gib es einem Schatzmeister per Handel oder Post: Es wird von selbst in der Schatzkammer eingetragen. Die Schatzmeister ernennt der Gildenmeister.",
  ["Día"] = "Tag",
  ["Día y hora"] = "Tag und Uhrzeit",
  ["Días anteriores:\n%s"] = "Vorherige Tage:\n%s",
  ["Días que dura"] = "Dauer in Tagen",
  ["Dónde (opcional)"] = "Wo (optional)",
  ["Dónde está la hermandad"] = "Wo die Gilde ist",
  ["Dónde está tu hermandad"] = "Wo deine Gilde ist",
  ["Dónde estás"] = "Wo du bist",
  ["Echa una partida de dados por puntos: contra la casa para practicar, o retando a alguien de la hermandad. Arena, pestaña «Taberna»."] = "Spiel eine Würfelpartie um Punkte: gegen das Haus zum Üben oder gegen jemanden aus der Gilde. Arena, Reiter «Taverne».",
  ["Editar"] = "Bearbeiten",
  ["Editar ficha"] = "Steckbrief bearbeiten",
  ["Editar la línea"] = "Die Zeile bearbeiten",
  ["Editar mi ficha"] = "Meinen Steckbrief bearbeiten",
  ["Editar operación"] = "Operation bearbeiten",
  ["Editar raid"] = "Schlachtzug bearbeiten",
  ["El Templo de Atal'Hakkar"] = "Der Tempel von Atal'Hakkar",
  ["El artesano"] = "Der Handwerker",
  ["El atajo Mayús + tecla de hermandad"] = "Das Kürzel Umschalt + Gildentaste",
  ["El botón de BlazonGuild en la ventana de hermandad del juego"] = "Die BlazonGuild-Schaltfläche im Gildenfenster des Spiels",
  ["El canal oculto de la alianza (su chat sigue por los mensajeros)"] = "Der versteckte Allianzkanal (der Chat läuft weiter über die Boten)",
  ["El chat de hermandad del juego no se puede silenciar desde un addon: ahí solo se oculta en BlazonGuild."] = "Der Gildenchat des Spiels kann von einem Addon nicht stummgeschaltet werden: Dort wird er nur in BlazonGuild ausgeblendet.",
  ["El chat de la alianza va también por un canal oculto del juego, así llega aunque falten mensajeros. Y la pestaña «Gestión» reúne los cargos y las invitaciones."] = "Der Allianzchat läuft auch über einen versteckten Spielkanal, so kommt er an, auch wenn Boten fehlen. Und der Reiter «Verwaltung» sammelt die Ämter und Einladungen.",
  ["El chat de oficiales del juego: solo lo leen los rangos con permiso."] = "Der Offizierschat des Spiels: Nur die Ränge mit Berechtigung lesen ihn.",
  ["El equipo, los talentos, los atributos y las profesiones de cada miembro, con sus tooltips, sin salir del juego."] = "Ausrüstung, Talente, Werte und Berufe jedes Mitglieds, mit ihren Tooltips, ohne das Spiel zu verlassen.",
  ["El escudo de honor en las ventanas de chat del juego"] = "Das Ehrenwappen in den Chatfenstern des Spiels",
  ["El grupo de %s para %s no puede llevarte esta vez."] = "Die Gruppe von %s für %s kann dich diesmal nicht mitnehmen.",
  ["El honor"] = "Die Ehrung",
  ["El idioma nuevo se aplica al recargar la interfaz."] = "Die neue Sprache gilt nach dem Neuladen der Oberfläche.",
  ["El jefe tiene que ser de tu hermandad."] = "Der Anführer muss aus deiner Gilde sein.",
  ["El juego"] = "Das Spiel",
  ["El juego no deja inspeccionarle ahora."] = "Das Spiel lässt ihn gerade nicht betrachten.",
  ["El juego no deja que un accesorio recargue la interfaz por sí solo."] = "Das Spiel lässt ein Addon die Oberfläche nicht selbst neu laden.",
  ["El juego no devolvió la tirada (/roll). Vuelve a pulsar «Sortear y empezar»."] = "Das Spiel hat den Wurf (/roll) nicht zurückgegeben. Drücke erneut «Auslosen und starten».",
  ["El juego no respondió; acércate y vuelve a probar."] = "Das Spiel hat nicht geantwortet; geh näher heran und versuch es noch einmal.",
  ["El juego solo deja inspeccionar de cerca (unos 30 metros). Desde lejos solo se ve el equipo de quien tiene BlazonGuild: acércate a él, o pídele que lo instale."] = "Das Spiel erlaubt Betrachten nur aus der Nähe (etwa 30 Meter). Aus der Ferne siehst du nur die Ausrüstung von Spielern mit BlazonGuild: geh näher hin oder bitte sie, es zu installieren.",
  ["El juego tardaba demasiado en responder; vuelve a pulsar."] = "Das Spiel hat zu lange gebraucht; drücke erneut.",
  ["El juego todavía no ha enviado la lista de miembros. Aparecerá en unos segundos."] = "Das Spiel hat die Mitgliederliste noch nicht gesendet. Sie erscheint in ein paar Sekunden.",
  ["El libro está vacío. Cuando alguien dé oro a un tesorero por comercio o correo, se apunta aquí solo."] = "Das Buch ist leer. Wenn jemand einem Schatzmeister Gold per Handel oder Post gibt, wird es hier von selbst eingetragen.",
  ["El líder"] = "Der Anführer",
  ["El líder de «%s» ha sacado a %s de la alianza."] = "Der Anführer von «%s» hat %s aus der Allianz entfernt.",
  ["El líder puede llamar a las armas a toda la alianza y darle una clave nueva."] = "Der Anführer kann die ganze Allianz zu den Waffen rufen und ihr einen neuen Schlüssel geben.",
  ["El líder puede ocultar a alguien en los chats comunes; la lista la ven los organizadores."] = "Der Anführer kann jemanden in den gemeinsamen Chats ausblenden; die Liste sehen die Organisatoren.",
  ["El maestro"] = "Der Gildenmeister",
  ["El maestro decide sobre %s"] = "Der Gildenmeister entscheidet über %s",
  ["El maestro ha decidido no mostrar los donantes."] = "Der Gildenmeister hat entschieden, die Spender nicht anzuzeigen.",
  ["El maestro ha decidido que el libro solo lo vean los oficiales y los tesoreros."] = "Der Gildenmeister hat entschieden, dass nur die Offiziere und Schatzmeister das Buch sehen.",
  ["El maestro la crea e invita a alguien de otra hermandad que tenga BlazonGuild. Su maestro la acepta o la rechaza."] = "Der Gildenmeister gründet sie und lädt jemanden aus einer anderen Gilde mit BlazonGuild ein. Dessen Gildenmeister nimmt an oder lehnt ab.",
  ["El maestro nombra a los capitanes (leen y escriben en «Oficiales de la alianza») y a los mensajeros (llevan los mensajes a las otras hermandades)."] = "Der Gildenmeister ernennt die Hauptleute (sie lesen und schreiben in «Offiziere der Allianz») und die Boten (sie bringen die Nachrichten zu den anderen Gilden).",
  ["El maestro nombra a los tesoreros en «Cuotas». Son quienes guardan el oro de la hermandad. El addon nunca mueve oro: solo lo apunta."] = "Der Gildenmeister ernennt die Schatzmeister unter «Beiträge». Sie verwahren das Gold der Gilde. Das Addon bewegt nie Gold: Es trägt es nur ein.",
  ["El maestro pulsa «Publicar nuestras cifras» en Rankings, pestaña «Hermandades». Se ven al jugar en grupo con alguien de otra hermandad que use BlazonGuild. Solo cifras de la hermandad, nada de nadie en concreto."] = "Der Gildenmeister klickt in Ranglisten, Reiter «Gilden», auf «Unsere Zahlen veröffentlichen». Man sieht sie beim Spielen in einer Gruppe mit jemandem einer anderen Gilde, der BlazonGuild nutzt. Nur Zahlen der Gilde, nichts über einzelne Personen.",
  ["El maestro%s invita a otras hermandades y decide si seguís en la alianza."] = "Der Gildenmeister%s lädt andere Gilden ein und entscheidet, ob ihr in der Allianz bleibt.",
  ["El mes de la hermandad: raids y eventos de BlazonGuild junto a los del calendario del juego."] = "Der Monat der Gilde: BlazonGuild-Schlachtzüge und -Ereignisse neben denen des Spielkalenders.",
  ["El modo capturas ha terminado: vuelves a ver tu hermandad."] = "Der Screenshot-Modus ist beendet: du siehst wieder deine Gilde.",
  ["El parte"] = "Der Bericht",
  ["El primero de cada ranking lleva ese honor: sale en su ficha, con un escudo dorado sobre su nombre en el juego y junto a lo que escribe en el chat."] = "Der Erste jeder Rangliste trägt diese Ehrung: Sie erscheint in seinem Steckbrief, mit einem goldenen Wappen über seinem Namen im Spiel und neben dem, was er im Chat schreibt.",
  ["El primero de cada ranking lleva su honor: sale en su ficha, con un escudo dorado sobre su nombre y en el chat."] = "Der Erste jeder Rangliste trägt ihre Ehrung: Sie erscheint in seinem Steckbrief, mit einem goldenen Wappen über seinem Namen und im Chat.",
  ["El punto del minimapa y la flecha ya no gastan nada mientras no hay nada que dibujar."] = "Die Punkte der Minikarte und der Pfeil kosten nichts, solange es nichts zu zeichnen gibt.",
  ["El tesorero"] = "Der Schatzmeister",
  ["El texto ya nunca queda debajo de los botones de la tarjeta."] = "Der Text liegt nie mehr unter den Knöpfen der Karte.",
  ["Elegir a quién…"] = "Wen wählen…",
  ["Elegir…"] = "Wählen…",
  ["Elige a alguien de tu hermandad."] = "Wähle jemanden aus deiner Gilde.",
  ["Elige a cada luchador de la lista (los miembros, por orden alfabético), o escribe parte de su nombre y la lista se queda solo con los que coinciden."] = "Wähle jeden Kämpfer aus der Liste (die Mitglieder, alphabetisch), oder tippe einen Teil seines Namens und die Liste zeigt nur die passenden.",
  ["Elige a dos luchadores distintos."] = "Wähle zwei verschiedene Kämpfer.",
  ["Elige a quién retar"] = "Wähle, wen du herausforderst",
  ["Elige el día y la hora."] = "Wähle den Tag und die Uhrzeit.",
  ["Elige la banda, el día y la hora."] = "Wähle den Schlachtzug, den Tag und die Uhrzeit.",
  ["Elige la banda, el día y la hora. Tu hermandad la verá al instante y se apuntará desde el juego con su rol."] = "Wähle den Schlachtzug, den Tag und die Uhrzeit. Deine Gilde sieht ihn sofort und meldet sich im Spiel mit ihrer Rolle an.",
  ["Elige para qué es el grupo: una mazmorra, una banda u otra actividad."] = "Wähle, wofür die Gruppe ist: ein Dungeon, ein Schlachtzug oder eine andere Aktivität.",
  ["Elige uno a la izquierda, o crea uno con «Nuevo»."] = "Wähle links einen aus, oder erstelle einen mit «Neu».",
  ["Empate"] = "Unentschieden",
  ["Empezar"] = "Starten",
  ["Empezar la temporada %s"] = "Saison %s starten",
  ["Empezar la velada"] = "Den Kampfabend starten",
  ["Empiezas tú: pulsa «Tirar» en la Taberna."] = "Du fängst an: Drücke «Werfen» in der Taverne.",
  ["En %s. "] = "In %s. ",
  ["En Artesanía y botín: busca el objeto y susurra al artesano o hazle un encargo. Los artesanos publican su profesión al abrirla en el juego."] = "In Handwerk und Beute: Suche den Gegenstand und flüstere den Handwerker an oder gib ihm einen Auftrag. Handwerker veröffentlichen ihren Beruf, wenn sie ihn im Spiel öffnen.",
  ["En Mapa, pestaña «Avistamientos», preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora. Nada se envía si nadie pregunta."] = "In Karte, Reiter «Sichtungen», fragst du, wo ein Spieler der anderen Fraktion gesehen wurde. Es antworten die Gildenmitglieder, die zustimmen, mit dem, was sie in der letzten Viertelstunde gesehen haben. Ohne Frage wird nichts gesendet.",
  ["En Mapa, pestaña «En el mapa», pulsa «Seguir» junto a su nombre: una flecha bajo el minimapa te lleva hasta él. Sirve con quien comparte su posición y con el punto de reunión."] = "In Karte, Reiter «Auf der Karte», drückst du «Folgen» neben dem Namen: Ein Pfeil unter der Minikarte führt dich hin. Das geht bei allen, die ihre Position teilen, und beim Treffpunkt.",
  ["En cola"] = "In der Warteschlange",
  ["En curso"] = "Läuft",
  ["En el chat, una pestaña para toda la alianza y otra para cada hermandad hermana; las salas de roles se comparten."] = "Im Chat ein Reiter für die ganze Allianz und einer für jede Schwestergilde; die Rollenräume werden geteilt.",
  ["En el de tu juego: español, inglés, alemán, francés, italiano, portugués o ruso. Para otro, en Administración, «Idioma del addon», o escribe /bg idioma en. Se aplica al recargar la interfaz."] = "In der deines Spiels: Spanisch, Englisch, Deutsch, Französisch, Italienisch, Portugiesisch oder Russisch. Für eine andere: Verwaltung, «Sprache des Addons», oder tippe /bg idioma de. Sie gilt nach dem Neuladen der Oberfläche.",
  ["En el juego, abre la ventana de tu profesión (por ejemplo, Herrería). BlazonGuild te pregunta si quieres que tu hermandad lo vea: di «Publicar»."] = "Öffne im Spiel das Fenster deines Berufs (zum Beispiel Schmiedekunst). BlazonGuild fragt, ob deine Gilde ihn sehen soll: Sag «Veröffentlichen».",
  ["En el mapa"] = "Auf der Karte",
  ["En el modo capturas no se hace nada en el juego: es solo una hermandad de ejemplo."] = "Im Screenshot-Modus passiert nichts im Spiel: es ist nur eine Beispielgilde.",
  ["En el nivel máximo"] = "Auf Höchststufe",
  ["En inglés y los demás idiomas: los títulos del Tablón y el Calendario, el oro de la Tesorería, la Arena, los grupos y la Sala de guerra ya salen traducidos."] = "Auf Englisch und in den anderen Sprachen: Die Titel von Brett und Kalender, das Gold der Schatzkammer, die Arena, die Gruppen und der Kriegsraum sind jetzt übersetzt.",
  ["En juego"] = "Läuft",
  ["En juego, %s luchadores. Cada combate lo decide el primer duelo entre los dos."] = "Läuft, %s Kämpfer. Jeden Kampf entscheidet das erste Duell zwischen den beiden.",
  ["En juego: cada combate lo decide el primer duelo entre los dos."] = "Läuft: Jeden Kampf entscheidet das erste Duell zwischen den beiden.",
  ["En la Arena, pestaña «Taberna». Tiras seis dados, apartas los que puntúan (unos, cincos, tríos…) y decides si sigues o te plantas. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a 3000."] = "In der Arena, Reiter «Taverne». Du wirfst sechs Würfel, legst die punktenden beiseite (Einsen, Fünfen, Drillinge…) und entscheidest, ob du weitermachst oder stehen bleibst. Bringt ein Wurf nichts, verlierst du die Punkte des Zuges. Wer 3000 erreicht, gewinnt.",
  ["En la Arena, pestaña «Torneos», pulsa «Nuevo». La gente se apunta; tú pulsas «Sortear y empezar» y sale el cuadro. Cada combate lo decide su duelo."] = "In der Arena, Reiter «Turniere», drücke «Neu». Die Leute melden sich an; du drückst «Auslosen und starten» und der Turnierbaum erscheint. Jeden Kampf entscheidet sein Duell.",
  ["En la Arena: %s."] = "In der Arena: %s.",
  ["En la Arena: %s. "] = "In der Arena: %s. ",
  ["En la Armería de BlazonGuild. Si dices que sí, compartes con tu hermandad lo que llevas puesto (lo mismo que ve quien te inspecciona en el juego), y se pone al día cuando te cambias."] = "In der Waffenkammer von BlazonGuild. Wenn du zustimmst, teilst du mit deiner Gilde, was du trägst (dasselbe, was jeder sieht, der dich im Spiel betrachtet), und es aktualisiert sich, wenn du dich umziehst.",
  ["En la app"] = "In der App",
  ["En la final contra %s. Enhorabuena al campeón."] = "Im Finale gegen %s. Glückwunsch an den Champion.",
  ["En la hermandad"] = "In der Gilde",
  ["En la pestaña «En el mapa», «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión, con los metros que faltan."] = "Im Reiter «Auf der Karte» setzt «Folgen» einen Pfeil unter die Minikarte, der dich zu einem Gildenmitglied oder zum Treffpunkt führt, mit der restlichen Entfernung.",
  ["En la pestaña «Quién fabrica qué», escribe el objeto (por ejemplo «poción») y verás quién sabe hacerlo. «Susurrar» abre el chat para hablarle."] = "Im Reiter «Wer stellt was her» tippe den Gegenstand (zum Beispiel «Trank») und du siehst, wer ihn herstellen kann. «Flüstern» öffnet den Chat, um mit ihm zu sprechen.",
  ["En la próxima entrega del addon"] = "In der nächsten Version des Addons",
  ["En la raid, pulsa «Grupos» y arrastra a cada uno a su grupo. Cuando la banda esté formada en el juego, «Colocar en la banda» los mueve de verdad."] = "Drücke im Schlachtzug «Gruppen» und ziehe jeden in seine Gruppe. Wenn der Schlachtzug im Spiel gebildet ist, verschiebt «In den Schlachtzug setzen» sie wirklich.",
  ["En la sección Chat aparecen las pestañas de la alianza: «Toda la alianza» y una por cada hermandad hermana."] = "Im Bereich Chat erscheinen die Reiter der Allianz: «Ganze Allianz» und einer für jede Schwestergilde.",
  ["En línea"] = "Online",
  ["En marcha: "] = "Läuft: ",
  ["En marcha: %s, %s."] = "Läuft: %s, %s.",
  ["En vivo"] = "Live",
  ["En vivo, hace %d s"] = "Live, vor %d s",
  ["En «Avistamientos» preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora."] = "In «Sichtungen» fragst du, wo ein Spieler der anderen Fraktion gesehen wurde. Es antworten die Gildenmitglieder, die zustimmen, mit dem, was sie in der letzten Viertelstunde gesehen haben.",
  ["En «Encargos», pide el objeto. El artesano pulsa «Lo hago» y luego «Hecho»; cuando lo tengas, pulsa «Recibido». Te avisamos en cada paso."] = "Unter «Aufträge» bestellst du den Gegenstand. Der Handwerker drückt «Mache ich» und dann «Fertig»; wenn du ihn hast, drücke «Erhalten». Wir sagen dir bei jedem Schritt Bescheid.",
  ["En «Retos» retas a quien esté conectado; si acepta, os avisamos. «Cara a cara» pone a dos luchadores frente a frente, con su vida en directo si están cerca. Sin oro."] = "In «Herausforderungen» forderst du heraus, wer online ist; nimmt er an, sagen wir es euch beiden. «Kopf an Kopf» stellt zwei Kämpfer gegenüber, mit ihrer Gesundheit live, wenn sie in der Nähe sind. Ohne Gold.",
  ["En «Retos» ves quién está conectado y puedes retarle. Si acepta, os avisamos a los dos. Aquí no se apuesta oro."] = "Unter «Herausforderungen» siehst du, wer online ist, und kannst ihn herausfordern. Nimmt er an, sagen wir euch beiden Bescheid. Hier wird kein Gold gewettet.",
  ["En «Torneos», cualquiera crea uno. Cada uno se apunta; quien lo dirige sortea con /roll y sale el cuadro. Cada combate lo decide el duelo entre los dos."] = "Unter «Turniere» kann jeder eines erstellen. Jeder meldet sich an; wer es leitet, lost mit /roll aus und der Turnierbaum erscheint. Jeden Kampf entscheidet das Duell zwischen den beiden.",
