  ["Jugadores de la otra facción que matan a gente de la hermandad fuera de mazmorras y campos de batalla. Quien los caza se lleva su recompensa."] = "Spieler der anderen Fraktion, die Gildenmitglieder außerhalb von Dungeons und Schlachtfeldern töten. Wer sie erlegt, bekommt ihr Kopfgeld.",
  ["Jugar"] = "Spielen",
  ["Jugar contra la casa"] = "Gegen das Haus spielen",
  ["La Arena"] = "Die Arena",
  ["La Ciudad Sumergida"] = "The Drowned City",
  ["La Masacre"] = "Düsterbruch",
  ["La Taberna"] = "Die Taverne",
  ["La alianza cuenta personas, no personajes: los alters cuentan una vez."] = "Die Allianz zählt Personen, nicht Charaktere: Twinks zählen einmal.",
  ["La alianza estaba cambiando en ese momento. Prueba otra vez."] = "Die Allianz änderte sich gerade. Versuche es noch einmal.",
  ["La alianza manda ahora a los nuevos a «%s», hasta las %s."] = "Die Allianz schickt Neue jetzt zu «%s», bis %s.",
  ["La alianza recibe una clave nueva, para que no puedan seguir escribiendo."] = "Die Allianz bekommt einen neuen Schlüssel, damit sie nicht weiterschreiben können.",
  ["La alianza tiene líder: el maestro de la hermandad que vote la mayoría de los maestros."] = "Die Allianz hat einen Anführer: den Gildenmeister der Gilde, die die Mehrheit der Gildenmeister wählt.",
  ["La alianza ya tiene diez hermandades."] = "Die Allianz hat schon zehn Gilden.",
  ["La alianza ya usa la clave nueva."] = "Die Allianz nutzt schon den neuen Schlüssel.",
  ["La banda ya estaba como en el plan."] = "Der Schlachtzug war schon wie im Plan.",
  ["La carta: qué quieres decir a los maestros"] = "Der Brief: was du den Gildenmeistern sagen willst",
  ["La casa"] = "Das Haus",
  ["La crean y la aceptan los maestros: ninguna hermandad entra sin que su maestro diga que sí."] = "Die Gildenmeister gründen sie und nehmen sie an: Keine Gilde tritt bei, ohne dass ihr Gildenmeister ja sagt.",
  ["La crónica empieza ahora: entradas, salidas, ascensos, raids y decisiones, según tu addon las ve."] = "Die Chronik beginnt jetzt: Beitritte, Austritte, Beförderungen, Schlachtzüge und Entscheidungen, so wie dein Addon sie sieht.",
  ["La cuota semanal"] = "Der Wochenbeitrag",
  ["La deciden los maestros"] = "Die Gildenmeister entscheiden",
  ["La escuadra está llena (15 con el jefe)."] = "Der Trupp ist voll (15 mit dem Anführer).",
  ["La guía sale sola la primera vez que abres Artesanía, Mapa, Alianza o Sala de guerra."] = "Die Anleitung erscheint von selbst, wenn du Handwerk, Karte, Allianz oder Kriegsraum zum ersten Mal öffnest.",
  ["La han recibido %s organizadores conectados."] = "Empfangen von %s Organisatoren online.",
  ["La hermandad"] = "Die Gilde",
  ["La hermandad de %s ya está en una alianza."] = "Die Gilde von %s ist schon in einer Allianz.",
  ["La hermandad no sale en la clasificación: lo decide el maestro. "] = "Die Gilde ist nicht in der Rangliste: Das entscheidet der Gildenmeister. ",
  ["La hermandad no sale: pulsa para publicar sus cifras (nada de nadie en concreto). "] = "Die Gilde erscheint nicht: Klicke, um ihre Zahlen zu veröffentlichen (nichts über einzelne Personen). ",
  ["La hermandad que lidera escribe cartas a los maestros, dice a qué hermandad van los nuevos y puede ocultar a alguien en los chats comunes. Y en la Sala de guerra, sus operaciones llegan a todas."] = "Die führende Gilde schreibt den Gildenmeistern Briefe, sagt, zu welcher Gilde die Neuen gehen, und kann jemanden in den gemeinsamen Chats ausblenden. Und im Kriegsraum erreichen ihre Operationen alle.",
  ["La hermandad que lidera la alianza planea la operación en su Sala de guerra eligiendo «Toda la alianza». Llega a la Sala de guerra de cada hermandad; cada uno responde allí y el líder ve cuántos van de cada una."] = "Die Gilde, die die Allianz anführt, plant die Operation in ihrem Kriegsraum mit «Ganze Allianz». Sie erreicht den Kriegsraum jeder Gilde; jeder antwortet dort und der Anführer sieht, wie viele aus jeder kommen.",
  ["La línea de BlazonGuild en el recuadro de un jugador"] = "Die BlazonGuild-Zeile im Tooltip eines Spielers",
  ["La mejor puntuación de la Arena de la hermandad."] = "Die beste Arenawertung der Gilde.",
  ["La mejor puntuación de la Arena esta temporada, con 5 combates o más."] = "Die beste Arena-Wertung dieser Saison, mit 5 Kämpfen oder mehr.",
  ["La prueba no ha vuelto"] = "Der Test ist nicht zurückgekommen",
  ["La puntuación"] = "Die Wertung",
  ["La sala de este evento de la Arena, para quien lucha y quien mira. Se cierra una semana después de crearlo."] = "Der Raum dieses Arena-Events, für Kämpfer und Zuschauer. Er schließt eine Woche nach der Erstellung.",
  ["La semana pasada: "] = "Letzte Woche: ",
  ["La temporada %s se cierra y se guarda con su campeón y su podio."] = "Saison %s wird abgeschlossen und mit ihrem Champion und Podium gespeichert.",
  ["La ventana de BlazonGuild, sus diálogos y sus avisos"] = "Das BlazonGuild-Fenster, seine Dialoge und Hinweise",
  ["La ventana «Cara a cara»"] = "Das Fenster «Kopf an Kopf»",
  ["Las Mazmorras"] = "Das Verlies",
  ["Las Minas de la Muerte"] = "Die Todesminen",
  ["Las capas"] = "Die Layer",
  ["Las cartas del líder de la alianza son para los maestros y los capitanes de cada hermandad."] = "Die Briefe des Allianzanführers sind für die Gildenmeister und Hauptleute jeder Gilde.",
  ["Las decisiones finales de moderación siguen siendo del maestro."] = "Die endgültigen Moderationsentscheidungen bleiben beim Gildenmeister.",
  ["Las demás hermandades ya lo saben."] = "Die anderen Gilden wissen es schon.",
  ["Las hermandades de vuestra facción que juegan con BlazonGuild y publican sus cifras. Se conocen al jugar en grupo con alguien de ellas."] = "Die Gilden eurer Fraktion, die mit BlazonGuild spielen und ihre Zahlen veröffentlichen. Man lernt sie kennen, wenn man mit jemandem von ihnen in einer Gruppe spielt.",
  ["Las hermandades la reciben solas; durante un minuto puede perderse algún mensaje."] = "Die Gilden erhalten es von selbst; eine Minute lang kann eine Nachricht verloren gehen.",
  ["Las inscripciones ya están cerradas."] = "Die Anmeldungen sind schon geschlossen.",
  ["Las listas para elegir a alguien ya no salen vacías: se hacen al abrirlas, y si no hay nadie lo dicen."] = "Die Listen zur Auswahl einer Person sind nicht mehr leer: Sie entstehen beim Öffnen, und wenn niemand da ist, steht das dort.",
  ["Las marcas"] = "Die Markierungen",
  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "Die Markierungen über Namensplaketten und der Ring am Zielporträt",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "Dungeons innerhalb einer Hauptstadt gehören ihrer Fraktion; die übrigen sind für alle (Die Todesminen und Burg Schattenfang werden jetzt beiden Fraktionen angezeigt).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "Dungeons und Schlachtzüge sind jetzt die von WoW Forever: seine 9 neuen Dungeons (Hall of Thanes, Ruinen von Lordaeron, City of Dalaran, Blackmaw Hold…) und seine drei Schlachtzüge, The Barrow Deeps, Hyjalgipfel und Onyxias Hort, mit den Namen des Spiels.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "Die anderen Gilden haben noch nicht gesagt, wie viele kommen.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "Die anderen Gilden sehen dich nicht online. Nachrichten der «Gildenmeister» anderer Gilden erreichen dich nicht, solange du verborgen bist.",
  ["Las otras hermandades vuelven a verte conectado."] = "Die anderen Gilden sehen dich wieder online.",
  ["Las próximas dos semanas"] = "Die nächsten zwei Wochen",
  ["Las próximas dos semanas (%s)"] = "Die nächsten zwei Wochen (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "Schlachtzüge werden zwischen den Addons deiner Gilde geteilt. Um sie zu erstellen, zu sehen und dich anzumelden, akzeptiere zuerst den Datenschutz.",
  ["Las salas de roles y el comercio se comparten con todas."] = "Die Rollenräume und der Handel werden mit allen geteilt.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "Wir haben gefragt, ob er sie teilt; warte auf die Antwort.",
  ["Le toca a %s%s"] = "%s ist an der Reihe%s",
  ["Le toca a %s…"] = "%s ist dran…",
  ["Levantar bandera"] = "Flagge hissen",
  ["Libro"] = "Buch",
  ["Libro de la tesorería"] = "Buch der Schatzkammer",
  ["Libro para todos: %s"] = "Buch für alle: %s",
  ["Liderazgo"] = "Führung",
  ["Llamada a los oficiales"] = "Aufruf an die Offiziere",
  ["Llamar a los oficiales"] = "Die Offiziere rufen",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "Kam über %s. «Einladen» schickt die Einladung des Spiels; «Nein» sagt es höflich.",
  ["Lleva un tabardo."] = "Trägt einen Wappenrock.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "Vom Addon von %s eingetragen, der verloren hat: Nur der Verlierer trägt den Kampf ein, damit sich niemand Siege gibt.",
  ["Lo comparte él mismo (%s)."] = "Er teilt sie selbst (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "Er teilt sie: du siehst sie, auch wenn er weit weg ist.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Wer das Addon hat, teilt es sofort; für den Rest kommt es über die Brücken-App von der Website.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Mitglieder mit dem Addon teilen es; für den Rest Battle.net über die Website.",
  ["Lo decide el maestro. Ahora: %s"] = "Das entscheidet der Gildenmeister. Jetzt: %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "Ihr erstes Duell entscheidet: Rechtsklick auf das Porträt des anderen, «Duell».",
  ["Lo hace %s."] = "%s stellt es her.",
  ["Lo hago"] = "Mache ich",
  ["Lo lleva %s"] = "%s trägt sie",
  ["Lo pide %s. %s%s"] = "Bestellt von %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "Du kannst es jederzeit in der Waffenkammer ändern.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "Du kannst es jederzeit in der Waffenkammer abschalten («Meine Ausrüstung teilen»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "Was jeder im Gildenchat sagt, mit oder ohne Addon. Was gesagt wurde, während du weg warst, gibt dir ein Begleiter mit BlazonGuild weiter.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "Was das Spiel selbst über dich meldet und für die Gilde zählt: deine Duelle mit Gildenmitgliedern, wer dich im PvP außerhalb von Dungeons tötet, das Gold, das du einem Schatzmeister gibst, und die Bosse, die ihr gemeinsam besiegt.",
  ["Lo que la hermandad debe saber"] = "Was die Gilde wissen sollte",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "Deine Gilde sieht, was du veröffentlichst: wer jeden Gegenstand herstellen kann, um dich anzuflüstern oder dir einen Auftrag zu geben. Es aktualisiert sich, wenn du den Beruf öffnest.",
  ["Lo que responde aquí"] = "Was es hier antwortet",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "Was deine Gilde aus dem Spiel veröffentlicht, ist auch auf der BlazonGuild-Website zu sehen.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "Was du im Addon tust: dich für einen Schlachtzug anmelden, eine Gruppe posten, dein Profil… Du entscheidest jedes Mal selbst.",
  ["Lo verás en la Armería en un momento."] = "Du siehst sie gleich in der Waffenkammer.",
  ["Lo verás todo en /bg."] = "Du siehst alles unter /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "Vom eigenen Client von %s gesehen (die Todesübersicht des Spiels).",
  ["Lo viste tú (%s)."] = "Du hast es gesehen (%s).",
  ["Lo último"] = "Neuestes",
  ["Lo último: %s"] = "Zuletzt: %s",
  ["Logros"] = "Erfolge",
  ["Los Baldíos"] = "Brachland",
  ["Los Humedales"] = "Sumpfland",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "Die Angemeldeten sehen ihn als abgesagt. Er kann durch Bearbeiten neu angesetzt werden.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "Änderungen der Allianz sind signiert: Niemand kann sie fälschen.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "Hauptleute lesen und schreiben in «Offiziere der Allianz»; Boten bringen die Nachrichten zu den anderen Gilden. Gib den Namen ein und wähle das Amt.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "Moderationsfälle und Verwarnungen liegen jetzt nur noch auf den Computern der Organisatoren.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "Frühere Kämpfe bleiben gespeichert, zählen aber nicht mehr.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "Wer in jeder Zone online ist, mit oder ohne BlazonGuild.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "Gegenstandslinks im Chat werden richtig angezeigt (früher waren sie kaputt), auch die gespeicherten.",
  ["Los grupos"] = "Die Gruppen",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "Gruppen werden zwischen den Addons deiner Gilde geteilt. Akzeptiere den Datenschutz, um sie zu sehen (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "Schlachtzugsbosse werden auch dann erfasst, wenn das Spiel nur den Vornamen liefert, und die Gildenrangliste prüft jetzt die Karten der anderen Gilden.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "Der Schlachtzugsleiter, wer ihn erstellt hat, und die Offiziere verschieben sie. Du siehst es so, wie es ist.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "Namen und was jeder schreibt (Notizen, Ankündigungen, Nachrichten) erscheinen so, wie sie sind, unübersetzt.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "Die Offiziere tragen ein, wer welchen Gegenstand bekam und warum, damit der nächste Schlachtzug beim schon Entschiedenen weitermacht. Ohne Gebote und ohne Gold.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "Die Offiziere erstellen kleine Trupps mit ihrem Anführer (zum Beispiel «Die Wölfe», für den Angriff). Der Anführer wählt seine Leute; der Trupp hat seinen eigenen Chat.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "Die Offiziere von %s sehen es schon. Sie laden dich im Spiel ein, wenn sie ja sagen.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "Die Offiziere schreiben den öffentlichen Steckbrief: was ihr macht, Sprache, wann ihr spielt und wen ihr sucht (zum Beispiel Heiler).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "Die Organisatoren aller Gilden der Allianz. Sonst liest es niemand.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "Die Organisatoren ernennen Schiedsrichter in der Arena. Ein Schiedsrichter kann die Kämpfe jedes Turniers von Hand entscheiden und ein versehentlich eingetragenes Duell entfernen.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Organisatoren können das Addon wie ein Mitglied sehen («Als Mitglied sehen»), und andere Addons können BlazonGuild lesen, wenn du es erlaubst.",
  ["Los puntos de los compañeros en el mapa del mundo"] = "Die Punkte der Gildenmitglieder auf der Weltkarte",
  ["Los puntos del minimapa y la flecha «Seguir»"] = "Die Minikartenpunkte und der Pfeil «Folgen»",
  ["Los que guardas valen %d."] = "Die behaltenen sind %d wert.",
  ["Los rankings"] = "Die Ranglisten",
  ["Los tesoreros"] = "Die Schatzmeister",
  ["Lotería de práctica"] = "Übungslotterie",
  ["Lotería de práctica: cada día, hasta 3 boletos gratis; un oficial sortea con /roll 1-100 y se anuncia quién acierta."] = "Übungslotterie: Jeden Tag bis zu 3 kostenlose Lose; ein Offizier zieht mit /roll 1-100, und es wird verkündet, wer trifft.",
  ["Lotería: ha salido el %s"] = "Lotterie: gezogen wurde die %s",
  ["Luchador 1"] = "Kämpfer 1",
  ["Luchador 2"] = "Kämpfer 2",
  ["Lugar: «%s»"] = "Ort: «%s»",
  ["Líder: %s, maestro de %s."] = "Anführer: %s, Gildenmeister von %s.",
  ["Maestro: %s. Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Gildenmeister: %s. Noch kein Kontakt: Er kommt, wenn sich jemand von ihnen mit BlazonGuild einloggt.",
  ["Maestros"] = "Gildenmeister",
  ["Mago"] = "Magier",
  ["Mano derecha"] = "Waffenhand",
  ["Mano izquierda"] = "Schildhand",
  ["Manos"] = "Hände",
  ["Mapa"] = "Karte",
  ["Mapa explica qué pasa al compartir tu posición, quién te ve y dónde, y abre el mapa del mundo."] = "Die Karte erklärt, was beim Teilen deiner Position passiert, wer dich sieht und wo, und öffnet die Weltkarte.",
  ["Mapa, pestaña «Avistamientos»: pregunta a tu hermandad dónde se vio a un jugador de la otra facción (responde quien lo acepta)."] = "Karte, Reiter «Sichtungen»: Frag deine Gilde, wo ein Spieler der anderen Fraktion gesehen wurde (es antwortet, wer zustimmt).",
  ["Mapa, pestaña «En el mapa»: «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión."] = "Karte, Reiter «Auf der Karte»: «Folgen» setzt einen Pfeil unter die Minikarte, der dich zu einem Gildenmitglied oder zum Treffpunkt führt.",
  ["Mapa: quien comparte su posición sale ahora también como un punto en tu minimapa."] = "Karte: Wer seine Position teilt, erscheint jetzt auch als Punkt auf deiner Minikarte.",
  ["Maraudon"] = "Maraudon",
  ["Marcar leída"] = "Als gelesen markieren",
  ["Marcas en el chat del juego"] = "Markierungen im Spielchat",
  ["Marcas en nombres y chat: no"] = "Markierungen an Namen und Chat: nein",
  ["Marcas en nombres y chat: sí"] = "Markierungen an Namen und Chat: ja",
  ["Marcas: el escudo sobre los nombres y el aro del retrato de tu objetivo ya no tocan en combate los marcos protegidos del juego, que podían sacar «Las acciones de interfaz han fallado debido a este add-on» en la lista de accesorios."] = "Markierungen: Das Wappen über Namen und der Ring am Porträt deines Ziels berühren im Kampf nicht mehr die geschützten Fenster des Spiels, was in der AddOn-Liste die Meldung über fehlgeschlagene Interface-Aktionen auslösen konnte.",
  ["Marjal Revolcafango"] = "Düstermarschen",
  ["Mayor donante"] = "Größter Spender",
  ["Mayores donantes (90 días)"] = "Größte Spender (90 Tage)",
  ["Mayús + clic en un objeto para ponerlo en un campo de BlazonGuild"] = "Umschalt + Klick auf einen Gegenstand, um ihn in ein BlazonGuild-Feld zu setzen",
  ["Mazmorra"] = "Dungeon",
  ["Mazmorra (5 jugadores)"] = "Dungeon (5 Spieler)",
  ["Mazmorras"] = "Dungeons",
  ["Mañana"] = "Morgen",
  ["Mañana hay boletos nuevos."] = "Morgen gibt es neue Lose.",
  ["Mejor artesano"] = "Bester Handwerker",
  ["Mejor cazador"] = "Bester Jäger",
  ["Mejor de la Arena"] = "Beste der Arena",
  ["Mejor reclutador"] = "Bester Werber",
  ["Mejores artesanos"] = "Beste Handwerker",
  ["Memoria"] = "Speicher",
  ["Mensaje borrado por la moderación"] = "Nachricht von der Moderation gelöscht",
  ["Mensaje del día: %s"] = "Nachricht des Tages: %s",
  ["Mensajero"] = "Bote",
  ["Mensajero de la hermandad"] = "Bote der Gilde",
  ["Mensajeros: %s."] = "Boten: %s.",
  ["Mensajes"] = "Nachrichten",
  ["Mensajes de esta sesión"] = "Nachrichten dieser Sitzung",
  ["Mensajes firmados del líder de la alianza para los maestros (y, si quiere, los capitanes). Salen en Alianza, pestaña «Cartas y avisos»; al marcarlas como leídas, el líder lo ve."] = "Signierte Nachrichten des Allianzanführers an die Gildenmeister (und, wenn er will, die Hauptleute). Sie erscheinen in Allianz, Reiter «Briefe und Hinweise»; markierst du sie als gelesen, sieht es der Anführer.",
  ["Mensajes por la hermandad"] = "Nachrichten über die Gilde",
  ["Mensajes procesados"] = "Verarbeitete Nachrichten",
  ["Mi ficha"] = "Mein Steckbrief",
  ["Miembros"] = "Mitglieder",
  ["Miembros con el addon conectados hace poco."] = "Mitglieder mit dem Addon, die kürzlich online waren.",
  ["Miembros en el nivel máximo."] = "Mitglieder auf Höchststufe.",
  ["Miembros nuevos que dicen que los trajo (180 días)."] = "Neue Mitglieder, die sagen, dass er sie mitgebracht hat (180 Tage).",
  ["Miembros que publican sus profesiones."] = "Mitglieder, die ihre Berufe veröffentlichen.",
  ["Miembros que se han conectado en los últimos 7 días."] = "Mitglieder, die in den letzten 7 Tagen online waren.",
  ["Miembros: %s (jefe)%s."] = "Mitglieder: %s (Anführer)%s.",
  ["Mientras tanto ya funcionan en vivo: Resumen, La hermandad, Raids, Mazmorras y Calendario."] = "In der Zwischenzeit funktionieren schon live: Übersicht, Die Gilde, Schlachtzüge, Dungeons und Kalender.",
  ["Minas de la Muerte"] = "Die Todesminen",
  ["Minimizada en %s"] = "Minimiert in %s",
  ["Minimizar"] = "Minimieren",
  ["Misiones"] = "Quests",
  ["Misiones en grupo"] = "Gruppenquests",
  ["Moderación"] = "Moderation",
  ["Moderación para los organizadores, con avisos y casos que decide el maestro."] = "Moderation für die Organisatoren, mit Verwarnungen und Fällen, über die der Gildenmeister entscheidet.",
  ["Moderar"] = "Moderieren",
  ["Moderar a %s"] = "%s moderieren",
  ["Modo capturas"] = "Screenshot-Modus",
  ["Modo capturas (/bg capturas, o «Capturas» en Administración): una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para enseñar BlazonGuild con todas las pantallas llenas. No sale nada de tu juego."] = "Screenshot-Modus (/bg capturas oder «Screenshots» in der Verwaltung): eine Beispielgilde mit erfundenen Namen, nur auf deinem Bildschirm, um BlazonGuild mit vollen Seiten zu zeigen. Nichts verlässt dein Spiel.",
  ["Modo capturas: una hermandad de ejemplo"] = "Screenshot-Modus: eine Beispielgilde",
  ["Modo mando"] = "Controller-Modus",
  ["Monasterio Escarlata"] = "Scharlachrotes Kloster",
  ["Montaña Roca Negra"] = "Der Schwarzfels",
  ["Montañas de Alterac"] = "Alteracgebirge",
  ["Monte Hyjal"] = "Hyjal",
  ["Mostrar a tu hermandad qué personajes son tuyos"] = "Deiner Gilde zeigen, welche Charaktere deine sind",
  ["Mostrarlos"] = "Sie zeigen",
  ["Mostrarme conectado"] = "Mich online zeigen",
  ["Muertes con honor y actividad JcJ de cada miembro y por clase."] = "Ehrenhafte Siege und PvP-Aktivität jedes Mitglieds und nach Klasse.",
  ["Muertes que ha causado: %s%s. Última víctima: %s."] = "Verursachte Tode: %s%s. Letztes Opfer: %s.",
  ["Muñecas"] = "Handgelenke",
  ["Más tarde"] = "Später",
  ["Nada"] = "Nichts",
  ["Nada en las próximas dos semanas: ni raids de BlazonGuild ni eventos en el calendario del juego. Las raids que cree cualquier miembro en Raids aparecerán aquí."] = "Nichts in den nächsten zwei Wochen: weder BlazonGuild-Schlachtzüge noch Ereignisse im Spielkalender. Die Schlachtzüge, die ein Mitglied unter Schlachtzüge erstellt, erscheinen hier.",
  ["Nadie"] = "Niemand",
  ["Nadie (acepta la privacidad para aparecer)"] = "Niemand (akzeptiere den Datenschutz, um zu erscheinen)",
  ["Nadie ahora. Las peticiones las ven los oficiales."] = "Gerade niemand. Die Anfragen sehen die Offiziere.",
  ["Nadie ahora. Las peticiones llegan mientras estás conectado; «Invitar» manda la invitación del juego."] = "Gerade niemand. Anfragen kommen, während du online bist; «Einladen» schickt die Einladung des Spiels.",
  ["Nadie coincide con la búsqueda."] = "Niemand passt zur Suche.",
  ["Nadie comparte ahora su posición. Cada uno lo enciende con «Compartir mi posición»."] = "Gerade teilt niemand seine Position. Jeder schaltet es mit «Meine Position teilen» ein.",
  ["Nadie con recompensa. Cuando alguien de la otra facción mate a un miembro fuera de mazmorras, aparecerá aquí por sí solo."] = "Niemand mit Kopfgeld. Wenn jemand der anderen Fraktion ein Mitglied außerhalb von Dungeons tötet, erscheint er hier von selbst.",
  ["Nadie conectado ahora mismo."] = "Gerade niemand online.",
  ["Nadie de la hermandad se llama así. Borra lo escrito para ver a todos."] = "Niemand in der Gilde heißt so. Lösche die Eingabe, um alle zu sehen.",
  ["Nadie de la lista sabe hacer «%s». En «Encargos» puedes pedirlo a quien sepa."] = "Niemand auf der Liste kann «%s» herstellen. Unter «Aufträge» kannst du es bei jemandem bestellen, der es kann.",
  ["Nadie de «%s» conectado ahora, o el nombre no es exacto."] = "Gerade niemand von «%s» online, oder der Name stimmt nicht genau.",
  ["Nadie elegido"] = "Niemand ausgewählt",
  ["Nadie en la hermandad."] = "Niemand in der Gilde.",
  ["Nadie en reserva."] = "Niemand in Reserve.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán con BlazonGuild las hermandades de este canal."] = "Hier hat noch niemand geschrieben. Fang du an: Die Gilden dieses Kanals lesen es mit BlazonGuild.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán los miembros con BlazonGuild."] = "Hier hat noch niemand geschrieben. Fang du an: Die Mitglieder mit BlazonGuild lesen es.",
  ["Nadie ha levantado bandera. Levanta la tuya arriba y la hermandad sabrá que buscas grupo."] = "Niemand hat eine Flagge gehisst. Hisse oben deine, und die Gilde weiß, dass du eine Gruppe suchst.",
  ["Nadie lo ha visto todavía."] = "Noch hat ihn niemand gesehen.",
  ["Nadie lo tenía."] = "Niemand hatte sie.",
  ["Nadie lo tenía. Mañana, más boletos gratis."] = "Niemand hatte sie. Morgen gibt es mehr kostenlose Lose.",
  ["Nadie más conectado ahora mismo."] = "Gerade sonst niemand online.",
  ["Nadie más de la hermandad está conectado ahora."] = "Gerade ist sonst niemand aus der Gilde online.",
  ["Nadie más está conectado ahora."] = "Sonst ist gerade niemand online.",
  ["Nadie te ha retado ahora. Cuando alguien lo haga, te sale aquí con «Aceptar» y «No».\n\nCómo se reta: pulsa «Retar» junto a alguien de la lista (tiene que estar conectado y con BlazonGuild). Si acepta, os avisamos a los dos.\n\nEl duelo lo empezáis desde el juego (clic derecho en su retrato, «Duelo»). Retar no es obligatorio: cualquier duelo entre dos de la hermandad con BlazonGuild cuenta."] = "Gerade hat dich niemand herausgefordert. Wenn es jemand tut, erscheint es hier mit «Annehmen» und «Nein».\n\nSo forderst du heraus: Drücke «Herausfordern» neben jemandem aus der Liste (er muss online sein und BlazonGuild haben). Nimmt er an, sagen wir euch beiden Bescheid.\n\nDas Duell beginnt ihr im Spiel (Rechtsklick auf sein Porträt, «Duell»). Herausfordern ist nicht nötig: Jedes Duell zwischen zwei Gildenmitgliedern mit BlazonGuild zählt.",
  ["Nadie tiene puntos apuntados."] = "Niemand hat eingetragene Punkte.",
  ["Nadie todavía"] = "Noch niemand",
  ["Nadie. El líder puede ocultar a un jugador o a una hermandad en los chats comunes durante un tiempo."] = "Niemand. Der Anführer kann einen Spieler oder eine Gilde eine Zeit lang in den gemeinsamen Chats ausblenden.",
  ["Naxxramas"] = "Naxxramas",
  ["Necesitas estar en una hermandad."] = "Du musst in einer Gilde sein.",
  ["Ninguna"] = "Keine",
  ["Ninguna encuesta abierta. Cualquiera puede preguntar a la hermandad: qué banda hacer, a qué hora quedar…"] = "Keine offene Umfrage. Jeder kann die Gilde fragen: welcher Schlachtzug, wann man sich trifft…",
  ["Ninguna. Cuando otra hermandad os invite, aparecerá aquí y vuestro maestro decidirá."] = "Keine. Wenn eine andere Gilde euch einlädt, erscheint es hier und euer Gildenmeister entscheidet.",
  ["Ninguno"] = "Keiner",
  ["Ninguno en esta versión"] = "Keiner in dieser Version",
  ["Ningún botón se sale de su panel: ahora lo comprueban las pruebas en todas las pantallas."] = "Kein Knopf ragt aus seinem Feld: Die Tests prüfen das jetzt auf allen Bildschirmen.",
  ["Ningún organizador con BlazonGuild está conectado ahora. Prueba más tarde."] = "Gerade ist kein Organisator mit BlazonGuild online. Versuche es später.",
  ["Nivel"] = "Stufe",
  ["Nivel %d"] = "Stufe %d",
  ["Nivel %d %s, %s"] = "Stufe %d %s, %s",
  ["Nivel %d %s, %s de %s"] = "Stufe %d %s, %s von %s",
  ["Nivel %s"] = "Stufe %s",
  ["Nivel %s%s"] = "Stufe %s%s",
  ["Nivel %s%s%s"] = "Stufe %s%s%s",
  ["Nivel %s%s."] = "Stufe %s%s.",
  ["Nivel %s, de %s"] = "Stufe %s, von %s",
  ["Nivel de objeto %s"] = "Gegenstandsstufe %s",
  ["Nivel medio"] = "Durchschnittsstufe",
  ["Nivel mínimo"] = "Mindeststufe",
  ["Nivel y logros en vivo del juego; equipo y JcJ, de los miembros con el addon y de la web."] = "Stufe und Erfolge live aus dem Spiel; Ausrüstung und PvP von den Mitgliedern mit dem Addon und von der Website.",
  ["Niveles en vivo del juego y raids de BlazonGuild."] = "Stufen live aus dem Spiel und BlazonGuild-Schlachtzüge.",
  ["Niveles en vivo del juego; los grupos se comparten entre los miembros con el addon y con la web."] = "Stufen live aus dem Spiel; die Gruppen werden zwischen den Mitgliedern mit dem Addon und der Website geteilt.",
  ["No"] = "Nein",
  ["No aceptar peticiones de capa"] = "Keine Layer-Anfragen annehmen",
  ["No compartes tu posición."] = "Du teilst deine Position nicht.",
  ["No cuenta para la Arena: %s no tiene BlazonGuild (el combate lo apunta el addon de quien pierde)."] = "Zählt nicht für die Arena: %s hat kein BlazonGuild (den Kampf trägt das Addon des Verlierers ein).",
  ["No cuenta para la Arena: no es de tu hermandad."] = "Zählt nicht für die Arena: nicht aus deiner Gilde.",
  ["No es de tu hermandad."] = "Nicht aus deiner Gilde.",
  ["No es tu turno."] = "Du bist nicht an der Reihe.",
  ["No está conectado"] = "Nicht online",
  ["No está en tu hermandad"] = "Nicht in deiner Gilde",
  ["No estáis en ninguna alianza."] = "Ihr seid in keiner Allianz.",
  ["No estás en ninguna hermandad."] = "Du bist in keiner Gilde.",
  ["No hay campañas. Una campaña junta oro para algo concreto (por ejemplo, 100 de oro para pociones de banda) y enseña cuánto falta."] = "Keine Kampagnen. Eine Kampagne sammelt Gold für etwas Bestimmtes (zum Beispiel 100 Gold für Schlachtzugstränke) und zeigt, wie viel fehlt.",
  ["No hay cuota semanal. %s"] = "Kein Wochenbeitrag. %s",
  ["No hay encargos. Pide un objeto a un artesano (o a quien sepa hacerlo): te avisamos cuando lo tome y cuando esté hecho."] = "Keine Aufträge. Bestelle einen Gegenstand bei einem Handwerker (oder bei jemandem, der ihn herstellen kann): Wir sagen Bescheid, wenn er ihn übernimmt und wenn er fertig ist.",
  ["No hay grupos abiertos ahora. Crea uno y tu hermandad podrá apuntarse por rol desde el juego."] = "Gerade keine offenen Gruppen. Erstelle eine, und deine Gilde kann sich im Spiel nach Rolle anmelden.",
  ["No hay nada que elegir ahora."] = "Gerade gibt es nichts zu wählen.",
  ["No hay operaciones planeadas."] = "Keine Operationen geplant.",
  ["No hay operaciones. Las planean los organizadores y los jefes de escuadra; cuando haya una, te avisamos y respondes desde aquí."] = "Keine Operationen. Die Organisatoren und Truppanführer planen sie; gibt es eine, sagen wir Bescheid und du antwortest hier.",
  ["No hay operaciones. Planea una: qué se hace, cuándo, dónde y qué escuadras van. Cada uno responde «Voy», «Reserva» o «No puedo»."] = "Keine Operationen. Plane eine: was, wann, wo und welche Trupps gehen. Jeder antwortet «Dabei», «Reserve» oder «Kann nicht».",
  ["No hay sitio"] = "Kein Platz",
  ["No llegaste a la capa de %s. Puedes intentarlo de nuevo."] = "Du bist nicht im Layer von %s angekommen. Du kannst es erneut versuchen.",
  ["No lleva tabardo."] = "Trägt keinen Wappenrock.",
  ["No lo comparte. Pulsa «Ver su equipo»: si está cerca, lo inspeccionas; si está lejos y tiene BlazonGuild, se lo pedimos.%s"] = "Er teilt sie nicht. Drück «Ausrüstung ansehen»: Ist er nah, betrachtest du ihn; ist er weit weg und hat BlazonGuild, fragen wir ihn.%s",
  ["No lo comparte. Si lo tienes cerca (tu objetivo, el ratón encima o en tu grupo), pulsa «Inspeccionar»: lo verás tú, sin enviarlo a nadie.%s"] = "Er teilt sie nicht. Wenn er in deiner Nähe ist (dein Ziel, unter der Maus oder in deiner Gruppe), klicke auf «Betrachten»: Du siehst es, ohne es jemandem zu schicken.%s",
  ["No molestar"] = "Nicht stören",
  ["No mostrarlos"] = "Sie nicht zeigen",
  ["No player named '%s' is currently playing."] = "No player named '%s' is currently playing.",
  ["No puede enviar nada, ni cambiar nada, ni leer lo privado."] = "Es kann nichts senden, nichts ändern und nichts Privates lesen.",
  ["No puedes cambiar esta raid: la gestionan quien la creó, quien la dirige y los organizadores."] = "Du kannst diesen Schlachtzug nicht ändern: Ihn verwalten, wer ihn erstellt hat, wer ihn leitet und die Organisatoren.",
  ["No puedes ocultar a tu propia hermandad."] = "Du kannst deine eigene Gilde nicht ausblenden.",
  ["No puedes retarte a ti mismo."] = "Du kannst dich nicht selbst herausfordern.",
  ["No puedo"] = "Kann nicht",
  ["No recluta ahora"] = "Rekrutiert gerade nicht",
  ["No responder cuando pregunten"] = "Nicht antworten, wenn gefragt wird",
  ["No se pudo"] = "Hat nicht geklappt",
  ["No se pudo (%s)."] = "Hat nicht geklappt (%s).",
  ["No se pudo enviar (%s)."] = "Konnte nicht senden (%s).",
  ["No se pudo firmar: abre /reload y vuelve a probar."] = "Signieren fehlgeschlagen: gib /reload ein und versuch es erneut.",
  ["No se pudo guardar"] = "Konnte nicht speichern",
  ["No se pudo guardar (%s)."] = "Konnte nicht speichern (%s).",
  ["No se pudo inspeccionar"] = "Betrachten nicht möglich",
  ["No se pudo invitar"] = "Konnte nicht einladen",
  ["No se pudo preguntar"] = "Konnte nicht fragen",
  ["No se pudo publicar (%s)."] = "Konnte nicht veröffentlichen (%s).",
  ["No se pudo sortear"] = "Konnte nicht auslosen",
  ["No se pudo ver su equipo"] = "Ausrüstung nicht sichtbar",
  ["No se pudo votar"] = "Konnte nicht abstimmen",
  ["No se pudo."] = "Das ging nicht.",
  ["No se puede en combate."] = "Im Kampf nicht möglich.",
  ["No se puede seguir"] = "Folgen nicht möglich",
  ["No tiene BlazonGuild: no se le puede retar y su duelo no contaría"] = "Hat kein BlazonGuild: Man kann ihn nicht herausfordern, und sein Duell würde nicht zählen",
  ["No tienes permiso para eso."] = "Dafür hast du keine Berechtigung.",
  ["No volvió: el juego bloquea mensajes aquí (banda, mazmorra o combate)"] = "Kam nicht zurück: Das Spiel blockiert hier Nachrichten (Schlachtzug, Dungeon oder Kampf)",
  ["No voy"] = "Nicht dabei",
  ["No, mantenerla"] = "Nein, beibehalten",
  ["No. Todo funciona dentro del juego, entre los addons de los miembros. No hay que registrarse en ningún sitio."] = "Nein. Alles funktioniert im Spiel, zwischen den Addons der Mitglieder. Du musst dich nirgends anmelden.",
  ["Nombra a los tesoreros y fija la cuota. Los interruptores deciden qué ven los miembros (los oficiales lo ven todo)."] = "Ernenne die Schatzmeister und lege den Beitrag fest. Die Schalter bestimmen, was die Mitglieder sehen (die Offiziere sehen alles).",
  ["Nombrar"] = "Ernennen",
  ["Nombre"] = "Name",
  ["Nombre de la alianza"] = "Name der Allianz",
  ["Nombre de un jugador de la otra facción"] = "Name eines Spielers der anderen Fraktion",
  ["Nombre de un miembro"] = "Name eines Mitglieds",
  ["Nombre exacto, por ejemplo C A Ñ A D A"] = "Genauer Name, zum Beispiel C A Ñ A D A",
  ["Nombre y apellido"] = "Vor- und Nachname",
  ["Nombre y apellido (opcional)"] = "Vor- und Nachname (optional)",
  ["Nombre y especialidad"] = "Name und Spezialität",
  ["Nombre, rango, clase o zona"] = "Name, Rang, Klasse oder Zone",
  ["Nombre: por ejemplo, Raid del viernes"] = "Name: zum Beispiel Freitags-Schlachtzug",
  ["Nombres del juego"] = "Namen aus dem Spiel",
  ["Nombres en las líneas del juego"] = "Namen in den Zeilen des Spiels",
  ["Normal"] = "Normal",
  ["Nota (opcional)"] = "Notiz (optional)",
  ["Nota de la hermandad: %s"] = "Gildennotiz: %s",
  ["Nota para la hermandad (opcional)"] = "Notiz für die Gilde (optional)",
  ["Nota para quien lo lea (opcional)"] = "Notiz für den Leser (optional)",
  ["Nota: %s"] = "Notiz: %s",
  ["Notas de botín"] = "Beutenotizen",
  ["Notas de botín para los organizadores (a quién se dio qué y por qué), con puntos opcionales a mano. Sin pujas ni oro."] = "Beutenotizen für die Organisatoren (wer was bekam und warum), mit optionalen Punkten von Hand. Ohne Gebote und ohne Gold.",
  ["Novedades de BlazonGuild %s"] = "Neues in BlazonGuild %s",
  ["Nueva Armería: el equipo de cada uno, ranura a ranura, si lo comparte (pulsa «Compartir mi equipo»), o si lo inspeccionas tú de cerca."] = "Neue Waffenkammer: die Ausrüstung jedes Einzelnen, Platz für Platz, wenn er sie teilt (klicke auf «Meine Ausrüstung teilen») oder wenn du ihn aus der Nähe betrachtest.",
  ["Nueva Sala de guerra: escuadras con su jefe y su propio chat."] = "Neuer Kriegsraum: Trupps mit ihrem Anführer und eigenem Chat.",
  ["Nueva campaña"] = "Neue Kampagne",
  ["Nueva clave"] = "Neuer Schlüssel",
  ["Nueva clave para la alianza"] = "Neuer Schlüssel für die Allianz",
  ["Nueva escuadra"] = "Neuer Trupp",
  ["Nueva hermandad hermana"] = "Neue Schwestergilde",
  ["Nueva operación"] = "Neue Operation",
  ["Nueva raid"] = "Neuer Schlachtzug",
  ["Nueva raid: %s"] = "Neuer Schlachtzug: %s",
  ["Nueva sala"] = "Neuer Raum",
  ["Nueva sección Alianza: une tu hermandad con otras (lo deciden los maestros)."] = "Neuer Bereich Allianz: Verbinde deine Gilde mit anderen (die Gildenmeister entscheiden).",
  ["Nueva sección Arena: duelos entre miembros con su clasificación. El resultado lo lee el propio juego."] = "Neuer Bereich Arena: Duelle zwischen Mitgliedern mit Rangliste. Das Spiel selbst liest das Ergebnis.",
  ["Nueva sección Artesanía y botín: al abrir tu profesión, puedes publicarla para tu hermandad."] = "Neuer Bereich Handwerk und Beute: Wenn du deinen Beruf öffnest, kannst du ihn für deine Gilde veröffentlichen.",
  ["Nueva sección Chat: el chat de hermandad con más espacio y salas como Sanadores o Comercio."] = "Neuer Bereich Chat: der Gildenchat mit mehr Platz und Räumen wie Heiler oder Handel.",
  ["Nueva sección Mapa: cuántos compañeros hay en cada zona y quiénes son."] = "Neuer Bereich Karte: wie viele Begleiter in jeder Zone sind und wer sie sind.",
  ["Nueva sección Reclutamiento: la ficha pública de la hermandad, que escriben los oficiales."] = "Neuer Bereich Rekrutierung: der öffentliche Steckbrief der Gilde, den die Offiziere schreiben.",
  ["Nueva sección Tablón: anuncios, encuestas, turnos de palabra, la crónica y el resumen de la semana."] = "Neuer Bereich Brett: Ankündigungen, Umfragen, Wortmeldungen, die Chronik und die Wochenübersicht.",
  ["Nueva sección Tesorería: el libro de la hermandad se apunta solo cuando das oro a un tesorero (comercio o correo)."] = "Neuer Bereich Schatzkammer: Das Gildenbuch trägt sich von selbst ein, wenn du einem Schatzmeister Gold gibst (Handel oder Post).",
  ["Nueva sección «Se busca»: quien de la otra facción mate a uno de los vuestros fuera de mazmorras entra en la lista con su recompensa."] = "Neuer Bereich «Gesucht»: Wer von der anderen Fraktion einen von euch außerhalb von Dungeons tötet, kommt mit seinem Kopfgeld auf die Liste.",
  ["Nueva temporada"] = "Neue Saison",
  ["Nuevo"] = "Neu",
  ["Nuevo JcE: quién tiene nivel para cada banda, los jefes que lleva derrotados la hermandad (se apuntan solos) y las últimas raids."] = "Neues PvE: wer die Stufe für jeden Schlachtzug hat, die Bosse, die die Gilde besiegt hat (werden von selbst eingetragen), und die letzten Schlachtzüge.",
  ["Nuevo anuncio"] = "Neue Ankündigung",
  ["Nuevo botón redondo en el minimapa: un clic abre o cierra BlazonGuild; arrástralo para moverlo."] = "Neuer runder Knopf an der Minikarte: Ein Klick öffnet oder schließt BlazonGuild; zieh ihn, um ihn zu verschieben.",
  ["Nuevo botón «?» arriba: «Cómo funciona», una guía corta y con ejemplos de cada sección complicada."] = "Neuer «?»-Knopf oben: «So funktioniert es», eine kurze Anleitung mit Beispielen für jeden komplizierten Bereich.",
  ["Nuevo encargo"] = "Neuer Auftrag",
  ["Nuevo honor en Rankings: Campeón de la Arena. Y arreglado: algunos botones salían sin texto."] = "Neue Ehrung in Ranglisten: Arena-Champion. Und behoben: Einige Knöpfe zeigten keinen Text.",
  ["Nuevo líder de la alianza"] = "Neuer Anführer der Allianz",
  ["Nuevo torneo o velada"] = "Neues Turnier oder neuer Kampfabend",
  ["Nunca se comparten tu BattleTag ni tu posición en el mapa sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Dein BattleTag und deine Position auf der Karte werden nie geteilt, ohne dass du sie extra akzeptierst, eins nach dem anderen. Wenn du nicht zustimmst, zeigt dir das Addon weiter deine Gilde, sendet aber nichts.",
  ["Nunca se comparten tu posición en el mapa, tu equipo, tus otros personajes, tu BattleTag ni dónde ves a enemigos sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Deine Position auf der Karte, deine Ausrüstung, deine anderen Charaktere, dein BattleTag und wo du Feinde siehst, werden nie geteilt, ohne dass du einzeln zustimmst, eins nach dem anderen. Wenn du nicht zustimmst, zeigt dir das Addon weiter deine Gilde, sendet aber nichts.",
  ["Nunca se han enfrentado"] = "Nie gegeneinander",
  ["Núcleo de Magma"] = "Geschmolzener Kern",
  ["Núcleo de Magma, Guarida Alanegra, Zul'Gurub, Ahn'Qiraj y Naxxramas ya no salen para elegir: no están en Forever. Una raid antigua que las usara se sigue viendo."] = "Geschmolzener Kern, Pechschwingenhort, Zul'Gurub, Ahn'Qiraj und Naxxramas werden nicht mehr angeboten: Es gibt sie in Forever nicht. Ein alter Schlachtzug mit ihnen wird weiter angezeigt.",
  ["O elígelo de la lista"] = "Oder wähle ihn aus der Liste",
  ["Objetivo (oro)"] = "Ziel (Gold)",
  ["Objeto %s"] = "Gegenstand %s",
  ["Objetos entregados y confirmados en los últimos 90 días.\n%s"] = "In den letzten 90 Tagen gelieferte und bestätigte Gegenstände.\n%s",
  ["Ocultar"] = "Ausblenden",
  ["Ocultarle en mi chat"] = "In meinem Chat ausblenden",
  ["Ocultarme"] = "Mich verbergen",
