  ["Português"] = "Português",
  ["Prefiere no compartirlo; inspecciónale cuando esté cerca."] = "Er möchte sie nicht teilen; betrachte ihn, wenn er in der Nähe ist.",
  ["Pregunta"] = "Frage",
  ["Pregunta a tu hermandad dónde se vio a un jugador de la otra facción. Responden quienes lo aceptan, con lo que su juego les enseñó en el último cuarto de hora."] = "Frag deine Gilde, wo ein Spieler der anderen Fraktion gesehen wurde. Es antworten alle, die zustimmen, mit dem, was ihnen ihr Spiel in der letzten Viertelstunde gezeigt hat.",
  ["Preguntar"] = "Fragen",
  ["Preguntar a la hermandad"] = "Die Gilde fragen",
  ["Preguntas de los nuevos: aquí nadie se ríe de nadie."] = "Fragen der Neuen: Hier lacht niemand über niemanden.",
