  ["Publicar nuestras cifras: no"] = "Unsere Zahlen veröffentlichen: nein",
  ["Publicar nuestras cifras: sí"] = "Unsere Zahlen veröffentlichen: ja",
  ["Puede decidir combates de los torneos y quitar duelos equivocados."] = "Kann Turnierkämpfe entscheiden und falsche Duelle entfernen.",
  ["Puede que el juego esté bloqueando mensajes aquí (banda, mazmorra o combate). Prueba fuera."] = "Vielleicht blockiert das Spiel hier Nachrichten (Schlachtzug, Dungeon oder Kampf). Versuche es draußen.",
  ["Puedes cambiar tu voto cuando quieras."] = "Du kannst deine Stimme jederzeit ändern.",
  ["Puedes dejar de publicarlo cuando quieras."] = "Du kannst die Veröffentlichung jederzeit beenden.",
  ["Puedes dejar que lo decida su duelo."] = "Du kannst es ihr Duell entscheiden lassen.",
  ["Puedes inspeccionarle cuando lo tengas cerca."] = "Du kannst ihn betrachten, wenn er in der Nähe ist.",
  ["Puedes quitarle el permiso cuando quieras con /bg api."] = "Du kannst die Erlaubnis jederzeit mit /bg api zurücknehmen.",
  ["Puedes retar a quien esté conectado; si acepta, os avisamos a los dos. Sin apuestas."] = "Du kannst jeden herausfordern, der online ist; nimmt er an, sagen wir euch beiden Bescheid. Ohne Wetten.",
  ["Puertas abiertas"] = "Offene Türen",
  ["Pulsa Ctrl+C para copiarlo y guárdalo fuera del juego (por ejemplo, en un documento)."] = "Drücke Strg+C, um es zu kopieren, und bewahre es außerhalb des Spiels auf (zum Beispiel in einem Dokument).",
  ["Pulsa aquí, escribe /bg o usa el escudo junto al minimapa."] = "Klick hier, tippe /bg oder nutze das Wappen an der Minikarte.",
  ["Pulsa cualquier tarjeta para desplegarla y leer todo su texto (vuelve a pulsar para recogerla)."] = "Klicke eine Karte an, um sie aufzuklappen und den ganzen Text zu lesen (erneut klicken zum Zuklappen).",
  ["Pulsa los dados que brillan."] = "Klick auf die leuchtenden Würfel.",
  ["Pulsa los que brillan para guardarlos."] = "Klick die leuchtenden an, um sie zu behalten.",
  ["Pulsa para abrirla otra vez. Arrástrala para moverla."] = "Klicke, um sie wieder zu öffnen. Zieh sie, um sie zu verschieben.",
  ["Pulsa para decidirlo a mano (si alguien no se presenta)."] = "Klicke, um es von Hand zu entscheiden (wenn jemand nicht erscheint).",
  ["Pulsa para leerla entera aquí."] = "Klicke, um sie hier ganz zu lesen.",
  ["Pulsa para recogerla."] = "Klicke, um sie zuzuklappen.",
  ["Pulsa para ver los %s primeros."] = "Klicke, um die ersten %s zu sehen.",
  ["Pulsa para ver qué compartes. /bg estado y /bg prueba dan más detalle."] = "Klicke, um zu sehen, was du teilst. /bg estado und /bg prueba geben mehr Details.",
  ["Pulsa un combate para decidirlo a mano."] = "Klicke einen Kampf an, um ihn von Hand zu entscheiden.",
  ["Pulsa «Compartir mi posición»: tus compañeros con BlazonGuild te verán como un punto en su mapa del mundo (tecla M) y en su minimapa. Solo tu hermandad."] = "Drück «Meine Position teilen»: Deine Gildenmitglieder mit BlazonGuild sehen dich als Punkt auf ihrer Weltkarte (Taste M) und ihrer Minikarte. Nur deine Gilde.",
  ["Pulsa «Compartir mi posición»: tus compañeros con BlazonGuild te verán como un punto en su mapa del mundo (tecla M). Solo tu hermandad."] = "Drücke «Meine Position teilen»: Deine Begleiter mit BlazonGuild sehen dich als Punkt auf ihrer Weltkarte (Taste M). Nur deine Gilde.",
  ["Pulsa «Pedir entrar» y a los oficiales conectados les llega la petición. «Invitar» manda la invitación del juego; el addon nunca invita solo."] = "Drücke «Um Aufnahme bitten», und die Offiziere online erhalten die Anfrage. «Einladen» schickt die Einladung des Spiels; das Addon lädt nie von selbst ein.",
  ["Pulsa «Pedir invitación» en su capa. Él decide si te invita; al llegar a su capa, el addon te saca del grupo solo."] = "Drücke «Um Einladung bitten» bei seinem Layer. Er entscheidet, ob er dich einlädt; kommst du in seinem Layer an, nimmt dich das Addon von selbst aus der Gruppe.",
  ["Pulsa «Voy», «Reserva» o «No puedo». Un cuarto de hora antes te lo recordamos; al empezar, te sale la alerta en pantalla."] = "Drücke «Dabei», «Reserve» oder «Kann nicht». Eine Viertelstunde vorher erinnern wir dich; zu Beginn erscheint der Alarm auf dem Bildschirm.",
  ["Puntos"] = "Punkte",
  ["Puntos (opcional)"] = "Punkte (optional)",
  ["Puntos de «Se busca» en 90 días: cada baja de un buscado da su recompensa más 1."] = "«Gesucht»-Punkte in 90 Tagen: Jeder Abschuss eines Gesuchten bringt sein Kopfgeld plus 1.",
  ["Puntúa: púlsalo para guardarlo"] = "Punktet: klicken zum Behalten",
