  ["Pícaro"] = "Schurke",
  ["Que lo decida el duelo"] = "Das Duell entscheiden lassen",
  ["Que lo usas, tu versión y lo que tú hagas en él (apuntarte, publicar un grupo, tu ficha). Lo decides en /bg privacidad."] = "Dass du es nutzt, deine Version und was du darin tust (anmelden, eine Gruppe posten, dein Steckbrief). Du entscheidest es unter /bg privacidad.",
  ["Que usas BlazonGuild y qué versión tienes."] = "Dass du BlazonGuild nutzt und welche Version du hast.",
  ["Quien busca hermandad"] = "Wer eine Gilde sucht",
  ["Quien busca hermandad la ve al pedirla a cualquiera de vosotros con BlazonGuild.%s"] = "Wer eine Gilde sucht, sieht ihn, indem er einen von euch mit BlazonGuild fragt.%s",
  ["Quien comparte su posición sale como un punto en tu mapa del mundo y en tu minimapa. «Seguir» pone una flecha bajo el minimapa que te lleva hasta él."] = "Wer seine Position teilt, erscheint als Punkt auf deiner Weltkarte und Minikarte. «Folgen» setzt einen Pfeil unter die Minikarte, der dich hinführt.",
  ["Quien lo instala ve un aviso que dice cómo abrirlo: /bg o el escudo junto al minimapa."] = "Wer es installiert, sieht einen Hinweis, wie man es öffnet: /bg oder das Wappen an der Minikarte.",
  ["Quien no tiene hermandad abre BlazonGuild, escribe vuestro nombre en Reclutamiento, ve vuestra ficha y pide entrar. Los oficiales le invitan con un clic."] = "Wer keine Gilde hat, öffnet BlazonGuild, tippt euren Namen unter Rekrutierung, sieht euren Steckbrief und bittet um Aufnahme. Die Offiziere laden ihn mit einem Klick ein.",
  ["Quien no tiene hermandad puede buscaros, ver vuestra ficha y pedir entrar; los oficiales le invitan con un clic."] = "Wer keine Gilde hat, kann euch suchen, euren Steckbrief sehen und um Aufnahme bitten; die Offiziere laden ihn mit einem Klick ein.",
