  ["Raid cancelada"] = "Schlachtzug abgesagt",
  ["Raid de BlazonGuild"] = "BlazonGuild-Schlachtzug",
  ["Raids"] = "Schlachtzüge",
  ["Raids (%s)"] = "Schlachtzüge (%s)",
  ["Raids (90 días)"] = "Schlachtzüge (90 Tage)",
  ["Raids de BlazonGuild que empezaron en los últimos 90 días."] = "BlazonGuild-Schlachtzüge, die in den letzten 90 Tagen begonnen haben.",
  ["Raids en las que estaba confirmado al empezar, en 90 días (las que ha visto este addon)."] = "Schlachtzüge, bei denen er zu Beginn bestätigt war, in 90 Tagen (die dieses Addon gesehen hat).",
  ["Raids: nuevo botón «Grupos», con los grupos de la banda como en el juego. Arrastra a cada uno a su grupo, o púlsalo y luego pulsa dónde va."] = "Schlachtzüge: neuer Knopf «Gruppen», mit den Schlachtzugsgruppen wie im Spiel. Zieh jeden in seine Gruppe, oder klicke ihn an und dann dorthin, wo er hin soll.",
  ["Raids: «Voy», «Quizá» y «No voy» se guardan al pulsarlos (y el rol, si ya estás apuntado)."] = "Schlachtzüge: «Dabei», «Vielleicht» und «Nicht dabei» werden beim Anklicken gespeichert (und die Rolle, wenn du schon angemeldet bist).",
  ["Rango"] = "Rang",
  ["Rangos"] = "Ränge",
  ["Rangos Oro, Plata y Bronce, cinturón de campeón y temporadas."] = "Ränge Gold, Silber und Bronze, Champion-Gürtel und Saisons.",
  ["Rangos y cinturón"] = "Ränge und Gürtel",
  ["Rangos y permisos del propio juego; lo que se cambie se refleja en la web."] = "Ränge und Berechtigungen aus dem Spiel selbst; was sich ändert, erscheint auch auf der Website.",
  ["Ranking de donantes para todos: %s"] = "Spender-Rangliste für alle: %s",
  ["Rankings"] = "Ranglisten",
  ["Rankings y honores"] = "Ranglisten und Ehrungen",
  ["Rankings y honores: los primeros de cada podio llevan un escudo dorado sobre su nombre, en el chat y su honor en la ficha."] = "Ranglisten und Ehrungen: Die Ersten jedes Podiums tragen ein goldenes Wappen über ihrem Namen, im Chat und ihre Ehrung im Steckbrief.",
  ["Rankings, nueva pestaña «Hermandades»: la clasificación de las hermandades con BlazonGuild y la comparativa con la vuestra. Sale la vuestra si el maestro lo activa."] = "Ranglisten, neuer Reiter «Gilden»: die Rangliste der Gilden mit BlazonGuild und der Vergleich mit eurer. Eure erscheint, wenn der Gildenmeister es einschaltet.",
  ["Ratón y teclado"] = "Maus und Tastatur",
  ["Recargar ahora"] = "Jetzt neu laden",
  ["Rechazar"] = "Ablehnen",
  ["Recibido"] = "Erhalten",
  ["Reclutamiento"] = "Rekrutierung",
  ["Reclutando"] = "Rekrutiert",
  ["Recompensa %s"] = "Kopfgeld %s",
  ["Recompensa %s. Ha matado a %s%s. Cuidado."] = "Kopfgeld %s. Hat %s%s getötet. Vorsicht.",
  ["Rendirme"] = "Aufgeben",
  ["Rendirse"] = "Aufgeben",
  ["Repartir solos"] = "Automatisch verteilen",
  ["Reserva"] = "Reserve",
  ["Responde y acude"] = "Antworte und komm",
  ["Responder cuando pregunten"] = "Antworten, wenn gefragt wird",
  ["Respuestas: %s."] = "Antworten: %s.",
  ["Resumen"] = "Übersicht",
  ["Retar"] = "Herausfordern",
  ["Retar y mirar"] = "Herausfordern und zusehen",
  ["Retirar"] = "Zurückziehen",
  ["Reto aceptado: retadle desde el juego (clic derecho en su retrato, «Duelo»)."] = "Herausforderung angenommen: Fordert ihn im Spiel heraus (Rechtsklick auf sein Porträt, «Duell»).",
  ["Reto enviado"] = "Herausforderung gesendet",
  ["Retos"] = "Herausforderungen",
  ["Reunión"] = "Treffen",
  ["Reunión aquí"] = "Treffen hier",
  ["Reunión con %s"] = "Treffen mit %s",
  ["Reunión de oficiales, por favor: conectad con %s."] = "Offizierstreffen, bitte: Meldet euch bei %s.",
  ["Revisar"] = "Prüfen",
  ["Revisar la privacidad"] = "Datenschutz prüfen",
  ["Revisión completa del addon. En Forever el juego da los nombres de otra forma («El», o «El-Peregrino»), y por eso los duelos no se apuntaban, las tiradas de los Huesos y la lotería no se leían, el oro por comercio o correo se apuntaba a otro nombre y «Ver su equipo» no encontraba a nadie cerca. Arreglado."] = "Eine vollständige Überprüfung des Addons. Auf Forever liefert das Spiel Namen anders («El» oder «El-Peregrino»), deshalb wurden Duelle nicht erfasst, Würfe bei Knochen und Lotterie nicht gelesen, Gold per Handel oder Post unter einem anderen Namen erfasst, und «Ausrüstung ansehen» fand niemanden in der Nähe. Behoben.",
  ["Rodando…"] = "Rollt…",
  ["Rol habitual: %s"] = "Übliche Rolle: %s",
  ["Ronda %s"] = "Runde %s",
  ["Ruinas de Ahn'Qiraj"] = "Ruinen von Ahn'Qiraj",
  ["Ruinas de Lordaeron"] = "Ruinen von Lordaeron",
  ["SHIFT-%s"] = "SHIFT-%s",
  ["Sabe hacer: %s."] = "Kann herstellen: %s.",
  ["Sacar a %s de la alianza"] = "%s aus der Allianz entfernen",
  ["Sacerdote"] = "Priester",
  ["Sal antes de tu grupo: la invitación es a uno nuevo."] = "Verlass zuerst deine Gruppe: Die Einladung ist in eine neue.",
  ["Sala"] = "Raum",
  ["Sala de guerra"] = "Kriegsraum",
  ["Sala de guerra: la hermandad que lidera la alianza puede planear operaciones de toda la alianza; llegan a todas las hermandades y cada una responde en la suya."] = "Kriegsraum: Die Gilde, die die Allianz anführt, kann Operationen der ganzen Allianz planen; sie erreichen alle Gilden und jede antwortet in ihrer eigenen.",
  ["Salas"] = "Räume",
  ["Salas, con la alianza"] = "Räume, mit der Allianz",
  ["Saldo"] = "Saldo",
  ["Saldo para todos: %s"] = "Saldo für alle: %s",
  ["Sale en el idioma de tu juego. En Administración, «Idioma del addon», eliges otro; se aplica al recargar la interfaz."] = "Es erscheint in der Sprache deines Spiels. In Verwaltung, «Sprache des Addons», wählst du eine andere; sie gilt nach dem Neuladen der Oberfläche.",
  ["Salida"] = "Ausgabe",
  ["Salir"] = "Verlassen",
  ["Salir de la alianza"] = "Die Allianz verlassen",
  ["Salir de la cola"] = "Die Warteschlange verlassen",
  ["Salir de «%s»"] = "«%s» verlassen",
  ["Salto de capa sin terminar"] = "Unbeendeter Layer-Wechsel",
  ["Saludar por susurro"] = "Per Flüstern grüßen",
  ["Salís en la clasificación. "] = "Ihr seid in der Rangliste. ",
  ["Salón de los Feudales"] = "Hall of Thanes",
  ["Sanador"] = "Heiler",
  ["Sanadores"] = "Heiler",
  ["Scholomance"] = "Scholomance",
  ["Se apunta solo cuando un tesorero recibe o da oro por comercio o por correo: entrada si se lo dan, salida si lo da él. El tesorero también puede apuntar a mano, y en cada línea poner el concepto (para qué es) y su campaña. «Copia de seguridad» saca el libro en texto para guardarlo fuera del juego."] = "Es wird von selbst eingetragen, wenn ein Schatzmeister Gold per Handel oder Post erhält oder gibt: Einnahme, wenn man es ihm gibt, Ausgabe, wenn er es gibt. Der Schatzmeister kann auch von Hand eintragen und in jeder Zeile den Zweck (wofür) und die Kampagne angeben. «Sicherung» gibt das Buch als Text aus, um es außerhalb des Spiels aufzubewahren.",
  ["Se busca"] = "Gesucht",
  ["Se busca: %s"] = "Gesucht: %s",
  ["Se cuenta con lo que la hermandad ya apunta en BlazonGuild. Encima de cada ranking dice cómo se cuenta."] = "Gezählt wird mit dem, was die Gilde schon in BlazonGuild einträgt. Über jeder Rangliste steht, wie gezählt wird.",
  ["Se guardan para poder corregirlos. Si me mandas una captura de esto, sé exactamente qué falló. Entre paréntesis, la versión del addon en la que pasó."] = "Sie werden gespeichert, damit man sie beheben kann. Wenn du mir einen Screenshot davon schickst, weiß ich genau, was schiefging. In Klammern die Addon-Version, in der es passierte.",
  ["Se ha quitado de la Armería de tus compañeros."] = "Sie wurde aus der Waffenkammer deiner Gildenkameraden entfernt.",
  ["Se juega por puntos: aquí no se apuesta oro."] = "Es wird um Punkte gespielt: hier wird kein Gold gesetzt.",
  ["Se lo hemos pedido"] = "Wir haben gefragt",
  ["Se pregunta una vez por cuenta del juego. Cámbialo cuando quieras con /bg privacidad."] = "Es wird einmal pro Spielaccount gefragt. Ändere es jederzeit mit /bg privacidad.",
  ["Se queda como cancelado para todos."] = "Es bleibt für alle abgesagt.",
  ["Se rindió"] = "Hat aufgegeben",
  ["Se sincroniza entre los miembros con el addon y se refleja en la web."] = "Es wird zwischen den Mitgliedern mit dem Addon synchronisiert und erscheint auch auf der Website.",
  ["Se verá en cuanto el juego envíe la lista."] = "Es erscheint, sobald das Spiel die Liste sendet.",
  ["Seguir"] = "Folgen",
  ["Seguir a alguien"] = "Jemandem folgen",
  ["Seguir compartiendo"] = "Weiter teilen",
  ["Seguir jugando"] = "Weiterspielen",
  ["Seguridad: nadie de otra hermandad puede meter nada en la vuestra (antes, un jugador de otra hermandad con el addon podía colaros un torneo, una sala de chat o un grupo)."] = "Sicherheit: Niemand aus einer anderen Gilde kann etwas in eure einschleusen (vorher konnte ein Spieler einer anderen Gilde mit dem Addon euch ein Turnier, einen Chatraum oder eine Gruppe unterschieben).",
  ["Semana tranquila por ahora: lo que pase aparecerá aquí."] = "Bisher eine ruhige Woche: Was passiert, erscheint hier.",
  ["Semifinales"] = "Halbfinale",
  ["Si acepta, empiezas tú."] = "Wenn er annimmt, fängst du an.",
  ["Si aceptas, os avisamos a los dos. El duelo lo empezáis desde el juego: clic derecho en su retrato, «Duelo»."] = "Wenn du annimmst, sagen wir euch beiden Bescheid. Das Duell beginnt ihr im Spiel: Rechtsklick auf sein Porträt, «Duell».",
  ["Si al tirar ningún dado puntúa, salen «huesos»: pierdes lo del turno y le toca al otro. Si guardas los seis, vuelves a tirarlos todos."] = "Wenn beim Wurf kein Würfel punktet, gibt es «Knochen»: du verlierst die Punkte des Zugs und der andere ist dran. Behältst du alle sechs, wirfst du alle wieder.",
  ["Si al tirar ningún dado puntúa: ¡huesos! Pierdes lo de este turno."] = "Wenn beim Wurf kein Würfel punktet: Knochen! Du verlierst die Punkte dieses Zugs.",
  ["Si alguien de la otra facción te mata fuera de mazmorras y campos de batalla, tu addon lo apunta solo, con el resumen de muerte del juego. Ese jugador entra en la lista."] = "Wenn dich jemand der anderen Fraktion außerhalb von Dungeons und Schlachtfeldern tötet, trägt dein Addon es von selbst ein, mit der Todesübersicht des Spiels. Dieser Spieler kommt auf die Liste.",
  ["Si dejas de compartir, tu addon deja de enviar al momento. Lo que ya enviaste lo conservan tus compañeros hasta que caduque."] = "Wenn du das Teilen beendest, sendet dein Addon sofort nichts mehr. Was du schon gesendet hast, behalten deine Begleiter, bis es abläuft.",
  ["Si el juego bloquea algo del addon, queda guardado con su origen en Administración, «Errores internos», para poder arreglarlo."] = "Wenn das Spiel etwas vom Addon blockiert, wird es mit seiner Herkunft unter Verwaltung, «Interne Fehler», gespeichert, damit es behoben werden kann.",
  ["Si el maestro pone cuota (por ejemplo, 5 de oro por semana), en «Resumen» ves cuánto has dado esta semana y cuánto te falta."] = "Wenn der Gildenmeister einen Beitrag festlegt (zum Beispiel 5 Gold pro Woche), siehst du unter «Übersicht», wie viel du diese Woche gegeben hast und wie viel fehlt.",
  ["Si es un error, %s o un oficial puede quitarlo."] = "Wenn es ein Fehler ist, kann %s oder ein Offizier es entfernen.",
  ["Si es un error, quien lo apuntó o un oficial puede quitarlo."] = "Wenn es ein Fehler ist, kann es entfernen, wer es eingetragen hat, oder ein Offizier.",
  ["Si instala BlazonGuild, podréis retaros y sus duelos contarán en la clasificación."] = "Installiert er BlazonGuild, könnt ihr euch herausfordern und seine Duelle zählen in der Rangliste.",
  ["Si le cazas tú, te llevas la recompensa; y si un buscado anda cerca, te avisa."] = "Erlegst du ihn, bekommst du das Kopfgeld; und ist ein Gesuchter in der Nähe, warnt es dich.",
  ["Si le das tú el golpe final, te llevas su recompensa más 1 punto, y su recompensa vuelve a cero. Los puntos de 90 días hacen el ranking de cazadores."] = "Landest du den Todesstoß, bekommst du sein Kopfgeld plus 1 Punkt, und sein Kopfgeld fällt auf null. Die Punkte aus 90 Tagen bilden die Jägerrangliste.",
  ["Si le invitas, el addon le saca del grupo al llegar."] = "Lädst du ihn ein, nimmt ihn das Addon bei seiner Ankunft aus der Gruppe.",
  ["Si le matas tú, te llevas %s puntos de cazador."] = "Tötest du ihn, bekommst du %s Jägerpunkte.",
  ["Si quieres ayudar, da oro a un tesorero (comercio o correo): se apunta solo."] = "Wenn du helfen willst, gib einem Schatzmeister Gold (Handel oder Post): Es wird von selbst eingetragen.",
  ["Si quieres, compartes tu posición y tu capa con la hermandad: salís como puntos en el mapa del mundo."] = "Wenn du willst, teilst du deine Position und deinen Layer mit der Gilde: Ihr erscheint als Punkte auf der Weltkarte.",
  ["Si sales ahora, gana %s."] = "Wenn du jetzt gehst, gewinnt %s.",
  ["Si tu hermandad usa puntos de botín, los organizadores los apuntan a mano: nada los suma ni los resta solo. Sin pujas ni oro."] = "Wenn deine Gilde Beutepunkte nutzt, tragen die Organisatoren sie von Hand ein: Nichts zählt sie von selbst hinzu oder ab. Ohne Gebote und ohne Gold.",
  ["Si vuestro maestro lo activa, unas cifras de la hermandad (cuántos sois, jefes derrotados…; nada de nadie en concreto) salen en la clasificación de hermandades, para quien juegue en grupo con vosotros."] = "Wenn euer Gildenmeister es einschaltet, erscheinen einige Zahlen der Gilde (wie viele ihr seid, besiegte Bosse…; nichts über einzelne Personen) in der Gildenrangliste, für alle, die mit euch in einer Gruppe spielen.",
  ["Siguiente"] = "Weiter",
  ["Silenciado"] = "Stummgeschaltet",
  ["Silenciado %s"] = "Stummgeschaltet %s",
  ["Silenciarle en las salas de BlazonGuild suma un aviso; al tercero se abre un caso que decide el maestro. Si comparte su BattleTag con los organizadores, alcanza a todos sus personajes."] = "Ihn in den BlazonGuild-Räumen stummzuschalten bringt eine Verwarnung; bei der dritten wird ein Fall eröffnet, über den der Gildenmeister entscheidet. Teilt er seinen BattleTag mit den Organisatoren, betrifft es alle seine Charaktere.",
  ["Sima Ígnea"] = "Flammenschlund",
  ["Sin aceptar: el addon no envía nada"] = "Nicht akzeptiert: Das Addon sendet nichts",
  ["Sin alianza"] = "Keine Allianz",
  ["Sin anuncios todavía. Los publican el maestro y los organizadores."] = "Noch keine Ankündigungen. Sie werden vom Gildenmeister und den Organisatoren veröffentlicht.",
  ["Sin anuncios. Publica el primero: toda la hermandad lo verá y sabrás quién lo ha leído."] = "Keine Ankündigungen. Veröffentliche die erste: Die ganze Gilde sieht sie, und du weißt, wer sie gelesen hat.",
  ["Sin cargo"] = "Kein Amt",
  ["Sin cargos. Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades."] = "Keine Ämter. Hauptleute lesen und schreiben in «Offiziere der Allianz»; Boten bringen die Nachrichten zu den anderen Gilden.",
  ["Sin combate"] = "Kein Kampf",
  ["Sin compartir con tu hermandad: pulsa aquí"] = "Nicht mit deiner Gilde geteilt: hier klicken",
  ["Sin concepto"] = "Ohne Zweck",
  ["Sin decir"] = "Nicht angegeben",
  ["Sin denuncias recibidas ni nadie silenciado ahora."] = "Keine Meldungen erhalten und gerade niemand stummgeschaltet.",
  ["Sin festividades en estas dos semanas."] = "Keine Feiertage in diesen zwei Wochen.",
  ["Sin grupo"] = "Ohne Gruppe",
  ["Sin hermandad"] = "Ohne Gilde",
  ["Sin invitación"] = "Ohne Einladung",
  ["Sin motivo anotado"] = "Kein Grund eingetragen",
  ["Sin notas. Apunta a quién se dio cada objeto y por qué: la próxima banda empieza de lo decidido."] = "Keine Notizen. Trage ein, wer welchen Gegenstand bekam und warum: Der nächste Schlachtzug beginnt beim schon Entschiedenen.",
  ["Sin notas. Los organizadores apuntan aquí a quién se dio cada objeto y por qué."] = "Keine Notizen. Die Organisatoren tragen hier ein, wer welchen Gegenstand bekam und warum.",
  ["Sin organizadores conectados"] = "Keine Organisatoren online",
  ["Sin peticiones todavía"] = "Noch keine Anfragen",
  ["Sin probar en esta sesión"] = "In dieser Sitzung nicht getestet",
  ["Sin raids próximas ni bandera en el tablón."] = "Keine kommenden Schlachtzüge und keine Flagge am Brett.",
  ["Sin respuesta"] = "Keine Antwort",
  ["Sin zona"] = "Ohne Zone",
  ["Sin árbitros: deciden los combates a mano quien dirige cada torneo y los organizadores."] = "Keine Schiedsrichter: Kämpfe entscheiden von Hand der Leiter jedes Turniers und die Organisatoren.",
  ["Sobre esta persona"] = "Über diese Person",
  ["Sobre los miembros de la hermandad sale vuestro escudo. Si no quieres ver las marcas (tampoco las del chat), quítalas abajo o con /bg marcas."] = "Über den Gildenmitgliedern erscheint euer Wappen. Willst du die Markierungen nicht sehen (auch nicht im Chat), schalte sie unten oder mit /bg marcas aus.",
  ["Solo %s"] = "Nur %s",
  ["Solo %s y %s: lo leen los miembros de las dos con BlazonGuild. %s"] = "Nur %s und %s: Die Mitglieder beider mit BlazonGuild lesen es. %s",
  ["Solo aparece quien lo tiene instalado, está conectado y ha aceptado la privacidad."] = "Es erscheint nur, wer es installiert hat, online ist und den Datenschutz akzeptiert hat.",
  ["Solo borrar el mensaje"] = "Nur die Nachricht löschen",
  ["Solo con miembros de tu hermandad que tengan el addon (y, más adelante, con las hermandades aliadas que acepte tu maestro)."] = "Nur mit Mitgliedern deiner Gilde, die das Addon haben (und später mit den verbündeten Gilden, die dein Gildenmeister akzeptiert).",
  ["Solo con miembros de tu hermandad que tengan el addon. Si vuestro maestro forma una alianza, también el chat de la alianza y quién está conectado, con esas hermandades; con ninguna otra."] = "Nur mit Mitgliedern deiner Gilde, die das Addon haben. Wenn euer Gildenmeister eine Allianz gründet, auch der Allianzchat und wer online ist, mit diesen Gilden; mit keiner anderen.",
  ["Solo cuando el addon de un miembro ve que le mata alguien de la otra facción fuera de mazmorras y campos de batalla. Nadie puede apuntar a otro a mano."] = "Nur wenn das Addon eines Mitglieds sieht, dass ihn jemand der anderen Fraktion außerhalb von Dungeons und Schlachtfeldern tötet. Niemand kann einen anderen von Hand eintragen.",
  ["Solo el líder de la raid, quien la creó y los oficiales pueden moverlos."] = "Nur der Schlachtzugsleiter, wer ihn erstellt hat, und die Offiziere können sie verschieben.",
  ["Solo el maestro de la hermandad puede cambiarlo."] = "Nur der Gildenmeister kann es ändern.",
  ["Solo el maestro de la hermandad puede hacerlo."] = "Nur der Gildenmeister kann es tun.",
  ["Solo el maestro decide si la hermandad sale en la clasificación."] = "Nur der Gildenmeister entscheidet, ob die Gilde in der Rangliste erscheint.",
  ["Solo el maestro%s puede crear una alianza o aceptar una invitación. Si conoces una hermandad amiga, cuéntaselo."] = "Nur der Gildenmeister%s kann eine Allianz gründen oder eine Einladung annehmen. Kennst du eine befreundete Gilde, sag es ihm.",
  ["Solo lo que llevas puesto, como lo ve cualquiera que te inspeccione en el juego."] = "Nur was du trägst, so wie jeder es sieht, der dich im Spiel betrachtet.",
  ["Solo lo ven los rangos que leen el chat de oficiales."] = "Nur die Ränge, die den Offizierschat lesen, sehen es.",
  ["Solo los maestros de las hermandades de la alianza."] = "Nur die Gildenmeister der Allianzgilden.",
  ["Solo los oficiales pueden hacerlo."] = "Nur die Offiziere können es tun.",
  ["Solo los oficiales sortean."] = "Nur die Offiziere ziehen.",
  ["Solo los oficiales ven quién ha pagado. Tu propia cuota está en «Resumen»."] = "Nur die Offiziere sehen, wer bezahlt hat. Deinen eigenen Beitrag siehst du unter «Übersicht».",
  ["Solo los organizadores de la hermandad que lidera la alianza."] = "Nur die Organisatoren der Gilde, die die Allianz anführt.",
  ["Solo los organizadores publican anuncios."] = "Nur die Organisatoren veröffentlichen Ankündigungen.",
  ["Solo los organizadores pueden hacerlo."] = "Nur die Organisatoren können es tun.",
  ["Solo quien lo apuntó o un oficial puede quitarlo."] = "Nur wer es eingetragen hat, oder ein Offizier kann es entfernen.",
  ["Solo quien lo dirige y los oficiales pueden hacerlo."] = "Nur der Leiter und die Offiziere können es tun.",
  ["Solo si lo activas en Mapa («Compartir mi posición y mi capa»), y solo tu hermandad. Está apagado hasta que lo enciendes."] = "Nur wenn du es in der Karte einschaltest («Meine Position und meinen Layer teilen»), und nur deine Gilde. Es ist aus, bis du es einschaltest.",
  ["Solo si lo activas en Mapa («Compartir mi posición»), y solo tu hermandad: te ven como un punto en su mapa y su minimapa. Está apagado hasta que lo enciendes."] = "Nur wenn du es in Karte einschaltest («Meine Position teilen»), und nur deine Gilde: Sie sehen dich als Punkt auf ihrer Karte und Minikarte. Es ist aus, bis du es einschaltest.",
  ["Solo tu escuadra: %s (jefe) y %s%s. Va por susurro a cada uno: nadie más lo lee."] = "Nur dein Trupp: %s (Anführer) und %s%s. Es geht per Flüstern an jeden: Sonst liest es niemand.",
  ["Solo. Al terminar un duelo entre dos de la hermandad, el juego dice quién ganó y el addon de quien pierde lo apunta. Así nadie puede darse victorias."] = "Von selbst. Am Ende eines Duells zwischen zwei Gildenmitgliedern sagt das Spiel, wer gewonnen hat, und das Addon des Verlierers trägt es ein. So kann sich niemand Siege geben.",
  ["Sorteando… (%s tiradas)"] = "Losen… (%s Würfe)",
  ["Sortear hoy"] = "Heute ziehen",
  ["Sortear y empezar"] = "Auslosen und starten",
  ["Sorteo con /roll: %s. "] = "Auslosung per /roll: %s. ",
  ["Stratholme"] = "Stratholme",
  ["Su addon apunta el combate: lo verás en la Arena en un momento."] = "Sein Addon trägt den Kampf ein: Du siehst ihn gleich in der Arena.",
  ["Su ficha"] = "Sein Steckbrief",
  ["Su mejor victoria: contra %s, que tenía %s."] = "Sein bester Sieg: gegen %s, der %s hatte.",
  ["Su recompensa"] = "Sein Kopfgeld",
