  ["Tesoreros: %s. "] = "Schatzmeister: %s. ",
  ["Tesorería"] = "Schatzkammer",
  ["Tesorería: el oro se escribe también como 2g 50s. Autoprueba: dice cómo escribe tu juego los nombres."] = "Gildenkasse: Gold kann auch als 2g 50s eingegeben werden. Selbsttest: zeigt, wie dein Spiel Namen schreibt.",
  ["Tesorería: las cantidades ya caben en sus cuadros. Rankings: los 10 primeros de cada honor, y ya no está el del nivel 60."] = "Schatzkammer: Die Beträge passen jetzt in ihre Felder. Ranglisten: die Top 10 jeder Ehrung, und die der Stufe 60 ist weg.",
  ["Texto (opcional)"] = "Text (optional)",
  ["The Barrow Deeps"] = "The Barrow Deeps",
  ["Tiene que estar cerca de ti (tu objetivo, el ratón encima o en tu grupo)."] = "Er muss in deiner Nähe sein (dein Ziel, unter der Maus oder in deiner Gruppe).",
  ["Tiene que estar conectado y con BlazonGuild."] = "Er muss online sein und BlazonGuild haben.",
  ["Tienes la palabra"] = "Du hast das Wort",
  ["Tienes que ser líder o ayudante de la banda."] = "Du musst Schlachtzugsleiter oder Assistent sein.",
  ["Tierras Inhóspitas"] = "Ödland",
  ["Tierras de la Peste del Este"] = "Östliche Pestländer",
  ["Tierras de la Peste del Oeste"] = "Westliche Pestländer",
  ["Tipo %s"] = "Typ %s",
  ["Tira los dados."] = "Wirf die Würfel.",
  ["Tira los que quedan, o plántate y súmalo."] = "Wirf den Rest, oder hör auf und schreib es gut.",
  ["Tira seis dados, aparta los que puntúan y decide: arriesgar con el resto o plantarte. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a %s. Los dados salen del /roll del juego."] = "Wirf sechs Würfel, lege die punktenden beiseite und entscheide: mit dem Rest riskieren oder stehen bleiben. Bringt ein Wurf nichts, verlierst du die Punkte des Zuges. Wer %s erreicht, gewinnt. Die Würfel kommen aus dem /roll des Spiels.",
  ["Tirando…"] = "Würfelt…",
  ["Tirar"] = "Werfen",
  ["Tirar %d %s"] = "%d %s werfen",
  ["Tirar %s%s"] = "%s%s werfen",
  ["Toda la alianza"] = "Ganze Allianz",
  ["Toda la alianza, de «%s»"] = "Die ganze Allianz, von «%s»",
  ["Toda la hermandad"] = "Ganze Gilde",
  ["Todavía no ha escrito nada sobre sí."] = "Hat noch nichts über sich geschrieben.",
  ["Todavía no has escrito nada. Pulsa «Editar mi ficha»."] = "Du hast noch nichts geschrieben. Drücke «Meinen Steckbrief bearbeiten».",
  ["Todavía no hay mensajes en esta sesión. Lo que se diga en el chat de hermandad aparecerá aquí."] = "In dieser Sitzung noch keine Nachrichten. Was im Gildenchat gesagt wird, erscheint hier.",
  ["Todavía no hay raids programadas en %s."] = "Noch keine Schlachtzüge in %s geplant.",
  ["Todos"] = "Alle",
  ["Todos empiezan con %s puntos. Ganar a alguien mejor que tú da más puntos; a alguien de más nivel, también."] = "Alle beginnen mit %s Punkten. Jemanden Besseren zu besiegen bringt mehr Punkte; jemanden mit höherer Stufe ebenfalls.",
  ["Todos empiezan con 1500. Ganar a alguien mejor da más puntos. Por ejemplo, en tus primeros combates y con el mismo nivel: ganar a uno de 1600 da unos 26; a uno de 1400, unos 14."] = "Alle beginnen mit 1500. Jemanden Besseren zu besiegen bringt mehr Punkte. Zum Beispiel in deinen ersten Kämpfen und auf gleicher Stufe: Ein Sieg gegen jemanden mit 1600 bringt etwa 26; gegen jemanden mit 1400 etwa 14.",
  ["Todos empiezan de cero. ¡Suerte!"] = "Alle fangen bei null an. Viel Glück!",
  ["Todos los apuntados tienen grupo."] = "Alle Angemeldeten haben eine Gruppe.",
  ["Todos los mensajes de la alianza llevan una marca hecha con su clave. Cámbiala si crees que la conoce alguien de fuera."] = "Alle Nachrichten der Allianz tragen eine Markierung aus ihrem Schlüssel. Ändere ihn, wenn du glaubst, dass ihn jemand von außen kennt.",
  ["Todos ven los grupos; los mueven el líder de la raid, quien la creó y los oficiales."] = "Alle sehen die Gruppen; der Schlachtzugsleiter, wer ihn erstellt hat, und die Offiziere verschieben sie.",
  ["Todos vuelven a empezar con %s puntos."] = "Alle beginnen wieder mit %s Punkten.",
  ["Torneo"] = "Turnier",
  ["Torneo, %s"] = "Turnier, %s",
  ["Torneo: %s"] = "Turnier: %s",
  ["Torneo: cada uno se apunta; al sortear sale el cuadro eliminatorio."] = "Turnier: Jeder meldet sich an; bei der Auslosung entsteht der K.-o.-Baum.",
  ["Torneos"] = "Turniere",
  ["Torneos y veladas"] = "Turniere und Kampfabende",
  ["Traerla"] = "Mitnehmen",
  ["Tres iguales: la cara × 100 (tres 4 = 400); tres 1 = 1000. Cada dado igual de más lo dobla."] = "Drei gleiche: Augenzahl × 100 (drei 4 = 400); drei 1 = 1000. Jeder weitere gleiche Würfel verdoppelt.",
  ["Tu addon apunta solo lo tuyo, con el resumen de muerte y tu golpe final."] = "Dein Addon trägt nur deine eigenen ein, mit der Todesübersicht und deinem Todesstoß.",
  ["Tu bandera en el tablón"] = "Deine Flagge am Brett",
  ["Tu equipo y su nivel"] = "Deine Ausrüstung und ihre Stufe",
  ["Tu ficha"] = "Dein Steckbrief",
  ["Tu firma aún no está en la alianza. La añade vuestro maestro la próxima vez que se conecte."] = "Deine Signatur ist noch nicht in der Allianz. Euer Gildenmeister fügt sie beim nächsten Einloggen hinzu.",
  ["Tu grupo"] = "Deine Gruppe",
  ["Tu grupo: %s"] = "Deine Gruppe: %s",
  ["Tu hermandad"] = "Deine Gilde",
  ["Tu hermandad dejará de ver el chat de la alianza y sus salas compartidas. Las demás hermandades siguen juntas."] = "Deine Gilde sieht den Allianzchat und seine gemeinsamen Räume nicht mehr. Die anderen Gilden bleiben zusammen.",
  ["Tu hermandad ve lo que llevas puesto en la Armería; se actualiza cuando cambias algo."] = "Deine Gilde sieht in der Waffenkammer, was du trägst; es aktualisiert sich, wenn du etwas wechselst.",
  ["Tu hermandad verá en «Artesanía y botín» lo que sabes fabricar de %s (%s/%s)."] = "Deine Gilde sieht unter «Handwerk und Beute», was du mit %s herstellen kannst (%s/%s).",
  ["Tu inscripción"] = "Deine Anmeldung",
  ["Tu mensaje volvió en %d ms. Ningún otro miembro conectado tiene BlazonGuild ahora."] = "Deine Nachricht kam in %d ms zurück. Kein anderes Mitglied online hat gerade BlazonGuild.",
  ["Tu nuevo rango, %s, es de organizador en BlazonGuild. A partir de ahora puedes:"] = "Dein neuer Rang, %s, ist ein Organisatorrang in BlazonGuild. Ab jetzt kannst du:",
  ["Tu posición en el mapa"] = "Deine Position auf der Karte",
  ["Tu rol en el grupo"] = "Deine Rolle in der Gruppe",
  ["Tu rol habitual"] = "Deine übliche Rolle",
  ["Tu vista"] = "Deine Ansicht",
  ["Tu voto dice que el maestro de %s lidere la alianza."] = "Deine Stimme sagt, dass der Gildenmeister von %s die Allianz anführen soll.",
  ["Tu voto es para %s."] = "Deine Stimme gilt %s.",
  ["Turno de palabra"] = "Wortmeldung",
  ["Turnos de palabra abiertos%s. En cola: %s."] = "Wortmeldungen offen%s. In der Warteschlange: %s.",
  ["Turnos de palabra cerrados.%s"] = "Wortmeldungen geschlossen.%s",
  ["Tus honores: %s."] = "Deine Ehrungen: %s.",
  ["Tus números de hoy: %s."] = "Deine Zahlen heute: %s.",
  ["Tus otros personajes aparecerán aquí si eliges mostrarlos en tu ficha."] = "Deine anderen Charaktere erscheinen hier, wenn du sie in deinem Steckbrief zeigen lässt.",
  ["Tus personajes en esta hermandad"] = "Deine Charaktere in dieser Gilde",
  ["Tus profesiones"] = "Deine Berufe",
  ["Título"] = "Titel",
  ["Título (opcional)"] = "Titel (optional)",
  ["Tú %s, %s %s  (a %s)"] = "Du %s, %s %s  (bis %s)",
  ["Tú: %s"] = "Du: %s",
  ["Uldaman"] = "Uldaman",
  ["Un 1 vale 100 y un 5 vale 50."] = "Eine 1 ist 100 wert und eine 5 ist 50 wert.",
  ["Un duelo"] = "Ein Duell",
  ["Un juego de dados de taberna. Tiras seis dados, guardas los que puntúan y decides: arriesgar con los que quedan o plantarte. Gana quien llega a %s. Los dados salen del /roll del juego, así que nadie hace trampas."] = "Ein Würfelspiel aus der Taverne. Du wirfst sechs Würfel, behältst die punktenden und entscheidest: mit dem Rest riskieren oder aufhören. Wer zuerst %s hat, gewinnt. Die Würfel kommen vom /roll des Spiels, also schummelt niemand.",
  ["Un jugador sin hermandad abre BlazonGuild, escribe vuestro nombre y ve vuestra ficha. Necesita que alguno de vosotros esté conectado con el addon."] = "Ein Spieler ohne Gilde öffnet BlazonGuild, tippt euren Namen und sieht euren Steckbrief. Einer von euch muss mit dem Addon online sein.",
  ["Un momento: escribes muy rápido."] = "Moment: Du schreibst sehr schnell.",
  ["Un ordenador con personajes en varias hermandades guarda lo de cada una por separado, también si dos se llaman igual."] = "Ein Computer mit Charakteren in mehreren Gilden hält die Daten jeder Gilde getrennt, auch wenn zwei gleich heißen.",
  ["Una alianza une tu hermandad con otras: chat común, una pestaña para cada hermandad y salas compartidas. Cada una sigue con su maestro."] = "Eine Allianz verbindet deine Gilde mit anderen: gemeinsamer Chat, ein Reiter für jede Gilde und gemeinsame Räume. Jede behält ihren Gildenmeister.",
  ["Una campaña junta oro para algo concreto, con su barra de progreso. En «Banco» ves lo que había la última vez que un oficial lo abrió."] = "Eine Kampagne sammelt Gold für etwas Bestimmtes, mit Fortschrittsbalken. Unter «Bank» siehst du, was beim letzten Öffnen durch einen Offizier darin war.",
  ["Una capa es una copia de la zona. Para jugar con alguien de otra, pídele invitación: él decide, y el addon te saca del grupo al llegar."] = "Ein Layer ist eine Kopie der Zone. Um mit jemandem in einem anderen zu spielen, bitte ihn um eine Einladung: Er entscheidet, und das Addon nimmt dich bei der Ankunft aus der Gruppe.",
  ["Una capa es una copia de la zona. Para saber la tuya no hace falta tocar nada aquí: en el juego, haz clic en dos personajes que no sean jugadores (un guardia, un vendedor, un bicho) o pasa el ratón por encima de ellos.%s"] = "Ein Layer ist eine Kopie der Zone. Um deinen herauszufinden, musst du hier nichts anfassen: Klicke im Spiel auf zwei Figuren, die keine Spieler sind (eine Wache, einen Händler, ein Tier), oder fahre mit der Maus darüber.%s",
  ["Una capa es una copia de la zona. Para saber la tuya, haz clic en el juego en dos personajes que no sean jugadores (por ejemplo, dos guardias)."] = "Ein Layer ist eine Kopie der Zone. Um deinen herauszufinden, klicke im Spiel auf zwei Figuren, die keine Spieler sind (zum Beispiel zwei Wachen).",
  ["Una guía corta de esta sección, paso a paso."] = "Eine kurze Anleitung zu diesem Bereich, Schritt für Schritt.",
  ["Una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para hacer capturas de cada pantalla. No sale nada de tu juego. Vuelve a la tuya con el mismo botón o /bg capturas."] = "Eine Beispielgilde mit erfundenen Namen, nur auf deinem Bildschirm, für Screenshots jeder Seite. Nichts verlässt dein Spiel. Zurück zu deiner mit derselben Taste oder /bg capturas.",
  ["Una hermandad de ejemplo, solo en tu pantalla: nombres inventados y nada sale de tu juego. Vuelve a la tuya con /bg capturas."] = "Eine Beispielgilde, nur auf deinem Bildschirm: erfundene Namen, und nichts verlässt dein Spiel. Zurück zu deiner mit /bg capturas.",
  ["Una hermandad sale de la alianza"] = "Eine Gilde verlässt die Allianz",
  ["Una partida de Huesos, a %s."] = "Eine Partie Knochen, bis %s.",
  ["Una partida de dados por puntos (a 3000). Ábrelo en la Arena, pestaña «Taberna»."] = "Eine Würfelpartie um Punkte (bis 3000). Öffne sie in der Arena, Reiter «Taverne».",
  ["Una raid cancelada se ve cancelada: solo su cabecera con «CANCELADA» y, para quien la gestiona, «Volver a programar» y «Borrar»."] = "Ein abgesagter Schlachtzug sieht abgesagt aus: nur sein Kopf mit «ABGESAGT» und, für den Verwalter, «Neu ansetzen» und «Löschen».",
  ["Unas palabras para sus oficiales (opcional)"] = "Ein paar Worte für ihre Offiziere (optional)",
  ["Unas palabras sobre ti (lo verá tu hermandad)"] = "Ein paar Worte über dich (deine Gilde sieht es)",
  ["Une %s con otras hermandades: chat común, salas compartidas y quién está conectado en todas."] = "Verbinde %s mit anderen Gilden: gemeinsamer Chat, gemeinsame Räume und wer in allen online ist.",
  ["Unirse a «%s»"] = "«%s» beitreten",
