  ["Usa BlazonGuild %s"] = "Nutzt BlazonGuild %s",
  ["V"] = "S",
  ["Vais por delante en %s de %s. Sus cifras son del %s."] = "Ihr liegt in %s von %s vorn. Ihre Zahlen sind vom %s.",
  ["Vallefresno"] = "Eschental",
  ["Varias hermandades amigas"] = "Mehrere befreundete Gilden",
  ["Varias hermandades amigas se unen. Cada una sigue siendo la misma, con su maestro y sus normas."] = "Mehrere befreundete Gilden schließen sich zusammen. Jede bleibt, wie sie ist, mit ihrem Gildenmeister und ihren Regeln.",
  ["Vega de Tuercespina"] = "Schlingendorntal",
