  ["Velada"] = "Kampfabend",
  ["Velada, %s%s"] = "Kampfabend, %s%s",
  ["Velada: %s"] = "Kampfabend: %s",
  ["Velada: al añadir un combate, eliges a cada luchador de una lista con los miembros por orden alfabético, o escribes parte del nombre para buscarlo."] = "Kampfabend: Beim Hinzufügen eines Kampfes wählst du jeden Kämpfer aus einer alphabetischen Mitgliederliste, oder tippst einen Teil des Namens, um ihn zu finden.",
  ["Velada: tú anuncias los combates (A contra B) y cada duelo decide el suyo."] = "Kampfabend: Du kündigst die Kämpfe an (A gegen B), und jedes Duell entscheidet seinen.",
  ["Venid a donde está %s"] = "Kommt dorthin, wo %s ist",
