  ["Voy"] = "Dabei",
  ["Vuelve a verla cuando quieras con el botón «?» de arriba."] = "Sieh sie dir jederzeit wieder mit dem «?»-Knopf oben an.",
  ["Vuelves a ver BlazonGuild con tu propio rango."] = "Du siehst BlazonGuild wieder mit deinem eigenen Rang.",
  ["Vuestra ficha"] = "Euer Steckbrief",
  ["Vuestra ficha pública, quién pide entrar y quién trae más gente. Quien no tiene hermandad os encuentra por el nombre y os pide entrar desde el juego."] = "Euer öffentlicher Steckbrief, wer um Aufnahme bittet und wer die meisten Leute bringt. Wer keine Gilde hat, findet euch über den Namen und bittet im Spiel um Aufnahme.",
  ["Vuestra ficha y quién pide entrar. La alianza manda ahora a los nuevos a «%s», hasta las %s."] = "Euer Profil und wer beitreten will. Die Allianz schickt Neue jetzt zu «%s», bis %s.",
  ["Vuestro mejor puesto: %sº de %s en %s. "] = "Euer bester Platz: %s. von %s in %s. ",
  ["Vuestro puesto: %sº"] = "Euer Platz: %s.",
  ["Ya está en esta escuadra."] = "Ist schon in diesem Trupp.",
  ["Ya está en la escuadra «%s»."] = "Ist schon im Trupp «%s».",
  ["Ya está en «Se busca», con %s de recompensa. Quien de la hermandad lo cace se la lleva."] = "Er steht jetzt unter «Gesucht», mit %s Kopfgeld. Wer aus der Gilde ihn erlegt, bekommt es.",
  ["Ya está lleno."] = "Es ist schon voll.",
  ["Ya estáis en una alianza."] = "Ihr seid schon in einer Allianz.",
  ["Ya estás en el grupo de %s. En cuanto el juego te pase a su capa, te sacamos del grupo."] = "Du bist schon in der Gruppe von %s. Sobald dich das Spiel in seinen Layer versetzt, nehmen wir dich aus der Gruppe.",
  ["Ya estás en su capa"] = "Du bist schon in seinem Layer",
  ["Ya estás en su grupo"] = "Du bist schon in seiner Gruppe",
  ["Ya le han cazado %s%s%s."] = "Er wurde schon %s%s%s erlegt.",
  ["Ya le has retado hace un momento."] = "Du hast ihn gerade erst herausgefordert.",
